-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_d36dc660725d5f', 'subj_math', 'trig-identities', 'Sum, difference and double-angle identities', '\sin(A \pm B) = \sin A\cos B \pm \cos A\sin B,\ \cos(A \pm B) = \cos A\cos B \mp \sin A\sin B,\ \sin 2A = 2\sin A\cos A,\ \cos 2A = \cos^2 A - \sin^2 A', 'Identities for sines and cosines of sums, differences and double angles; cos 2A also equals 2cos²A − 1 and 1 − 2sin²A.', '[{"symbol":"A, B","meaning":"angles"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_f9a7e179f86ddf', 'subj_math', 'dot-product', 'Dot product', '\mathbf{u}\cdot\mathbf{v} = u_1v_1 + u_2v_2 = |\mathbf{u}||\mathbf{v}|\cos\theta', 'The dot product of two vectors; θ is the angle between them. The vectors are orthogonal exactly when u·v = 0.', '[{"symbol":"\\mathbf{u}, \\mathbf{v}","meaning":"vectors"},{"symbol":"\\theta","meaning":"angle between them"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_a53114ff3260fb', 'subj_math', 'conic-equations', 'Ellipse and hyperbola', '\frac{(x - h)^2}{a^2} + \frac{(y - k)^2}{b^2} = 1, \qquad \frac{(x - h)^2}{a^2} - \frac{(y - k)^2}{b^2} = 1', 'Standard forms centered at (h, k). Ellipse: c² = a² − b² (a > b). Hyperbola: c² = a² + b², asymptotes y − k = ±(b/a)(x − h).', '[{"symbol":"a, b","meaning":"semi-axis lengths"},{"symbol":"c","meaning":"center-to-focus distance"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_0d2ed626e7ce07', 'subj_math', 'polar-conversion', 'Polar and rectangular coordinates', 'x = r\cos\theta,\ y = r\sin\theta,\ r^2 = x^2 + y^2,\ \tan\theta = \frac{y}{x}', 'Converting between polar (r, θ) and rectangular (x, y) coordinates; choose θ in the correct quadrant.', '[{"symbol":"r","meaning":"distance from the pole"},{"symbol":"\\theta","meaning":"angle from the positive x-axis"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_36450585294e70', 'subj_math', 'de-moivre', 'Polar form and De Moivre''s Theorem', 'z = r(\cos\theta + i\sin\theta), \qquad z^n = r^n(\cos n\theta + i\sin n\theta)', 'A complex number in polar (trigonometric) form, and its nth power. Multiplying complex numbers multiplies moduli and adds arguments.', '[{"symbol":"r","meaning":"modulus |z|"},{"symbol":"\\theta","meaning":"argument"}]', 'published');

-- Lesson: analyzing-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_85df8919e4d839', 'analyzing-functions', 'Domain, range and intervals of increase and decrease', 'Read domain and range in interval notation, find intervals where a function increases, decreases or is constant, locate relative extrema, and compute average rates of change.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_478da9ce05d539', 'les_85df8919e4d839', 1, 'Write domain and range in interval notation from graphs and formulas.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f960c52e1dac0', 'les_85df8919e4d839', 2, 'Identify intervals of increase and decrease and relative maxima and minima.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_691113e833530d', 'les_85df8919e4d839', 3, 'Compute the average rate of change of a function on an interval.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_478da9ce05d539', 'les_85df8919e4d839', 'learn', 1, 'definition', '{"term":"Increasing and decreasing","body":"$f$ is increasing on an interval if $x_1 < x_2$ implies $f(x_1) < f(x_2)$ there (the graph rises left to right), and decreasing if it falls. A relative maximum is a point higher than all nearby points; a relative minimum is lower."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f960c52e1dac0', 'les_85df8919e4d839', 'learn', 2, 'definition', '{"term":"Average rate of change","body":"On $[a, b]$: $\\dfrac{f(b) - f(a)}{b - a}$, the slope of the secant line through $(a, f(a))$ and $(b, f(b))$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_691113e833530d', 'les_85df8919e4d839', 'experiment', 3, 'activity', '{"activity":"polynomial-zeros","title":"Find where it rises and falls","params":{"a":0.25,"r1":-3,"m1":1,"r2":1,"m2":2,"r3":4,"m3":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca5e11c55269e0', 'les_85df8919e4d839', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Estimate the x-values of the relative maximum and minimum by eye. Between them the graph decreases. Intervals of increase or decrease are stated with x-values, never y-values."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df987923ac15d4', 'les_85df8919e4d839', 'learn', 5, 'worked_example', '{"title":"For $f(x) = x^3 - 3x$, find the extrema (given: turning points at $x = \\pm 1$) and intervals","steps":[{"latex":"f(-1) = 2,\\ f(1) = -2","explanation":"Relative max 2 at x = −1, relative min −2 at x = 1."},{"latex":"\\text{increasing on } (-\\infty, -1) \\cup (1, \\infty),\\ \\text{decreasing on } (-1, 1)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8729f55048f1bb', 'les_85df8919e4d839', 'learn', 6, 'worked_example', '{"title":"Average rate of change of $f(x) = x^2$ on $[1, 4]$","steps":[{"latex":"\\frac{16 - 1}{4 - 1} = 5","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d0debc9e03eec', 'les_85df8919e4d839', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Average speed is the average rate of change of position, and economists describe growth \"per year\" over a period. Instantaneous rates (calculus) come from shrinking the interval."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_478da9ce05d539', 'les_85df8919e4d839', 1, 'practice', 'short_text', 1, 'Write the domain of $f(x) = \sqrt{6 - x}$ in interval notation. Use the format (-inf,6].', '{"accept":["(-inf,6]","(-∞,6]"]}', '[]', '$6 - x \ge 0$, so $(-\infty, 6]$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f960c52e1dac0', 'les_85df8919e4d839', 2, 'practice', 'short_text', 2, 'Find the average rate of change of $f(x) = 2x^2 - x$ on $[0, 3]$.', '{"accept":["5"]}', '["$f(3) = 15$, $f(0) = 0$."]', '$15 / 3 = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_691113e833530d', 'les_85df8919e4d839', 3, 'practice', 'multiple_choice', 2, '$g(x) = -(x - 2)^2 + 5$ is increasing on…', '{"choices":["$(2, \\infty)$","$(-\\infty, 2)$","$(-\\infty, 5)$","$(5, \\infty)$"],"answer":1}', '["Opens down; vertex at x = 2."]', 'It rises until the vertex: $(-\infty, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca5e11c55269e0', 'les_85df8919e4d839', 4, 'review', 'short_text', 3, 'What is the range of $h(x) = 3 - |x + 1|$? Use the format (-inf,3].', '{"accept":["(-inf,3]","(-∞,3]"]}', '[]', 'The maximum is 3 at $x = -1$, so $(-\infty, 3]$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_85df8919e4d839', (SELECT id FROM concepts WHERE slug = 'domain-range'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e4ff0e38e6f9e3', 'subj_math', 'rate-of-change', 'Average rate of change', 'The change in output divided by the change in input over an interval.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_85df8919e4d839', (SELECT id FROM concepts WHERE slug = 'rate-of-change'));
