-- Lesson: change-in-tandem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cfcb6437796557', 'change-in-tandem', 'Change in tandem', 'Describe how input and output values change together, using increasing and decreasing behavior and whether the rate of change is itself increasing or decreasing (concavity).', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa6a5d02261e0e', 'les_cfcb6437796557', 1, 'Describe a function as increasing or decreasing from a graph, table or context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_71fa09843013cf', 'les_cfcb6437796557', 2, 'Identify whether the rate of change is increasing or decreasing (concave up or down).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e48c463f039703', 'les_cfcb6437796557', 3, 'Locate relative extrema and points of inflection where behavior changes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa6a5d02261e0e', 'les_cfcb6437796557', 'learn', 1, 'definition', '{"term":"Change in tandem","body":"A function describes how outputs change as inputs change. As $x$ increases, the output can increase or decrease, and the rate at which it does so can itself grow or shrink."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71fa09843013cf', 'les_cfcb6437796557', 'learn', 2, 'definition', '{"term":"Concavity","body":"A graph is concave up where its rate of change is increasing (it bends upward, like a cup) and concave down where its rate of change is decreasing. A point of inflection is where concavity changes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e48c463f039703', 'les_cfcb6437796557', 'learn', 3, 'worked_example', '{"title":"Table: $x$ = 0, 1, 2, 3, 4 and $y$ = 2, 5, 9, 14, 20","steps":[{"latex":"\\Delta y: 3, 4, 5, 6","explanation":"y is increasing."},{"latex":"\\text{the differences increase}","explanation":"The rate of change is increasing: concave up."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5205b18b9614b7', 'les_cfcb6437796557', 'learn', 4, 'worked_example', '{"title":"A cup of coffee cools: 90°, 75°, 64°, 56°, 51° at 5-minute intervals","steps":[{"latex":"\\Delta: -15, -11, -8, -5","explanation":"Decreasing."},{"latex":"\\text{the decreases shrink}","explanation":"Rate of change increasing (toward 0): concave up."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54ab1b9bfa4210', 'les_cfcb6437796557', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"\"Sales are rising, but more slowly\" describes an increasing function that''s concave down. News and business reports describe concavity all the time without the word."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa6a5d02261e0e', 'les_cfcb6437796557', 1, 'practice', 'multiple_choice', 1, '$y$ values 10, 8, 5, 1 for equally spaced $x$. The function is…', '{"choices":["Increasing, concave up","Decreasing, concave down","Decreasing, concave up","Increasing, concave down"],"answer":1}', '["Differences −2, −3, −4."]', 'Decreasing, and the rate is decreasing (more negative): concave down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_71fa09843013cf', 'les_cfcb6437796557', 2, 'practice', 'multiple_choice', 2, 'A population grows, but each year it adds fewer people than the year before. Its graph is…', '{"choices":["Increasing, concave up","Increasing, concave down","Decreasing, concave up","Linear"],"answer":1}', '[]', 'Increasing with a decreasing rate: concave down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e48c463f039703', 'les_cfcb6437796557', 3, 'practice', 'multiple_choice', 2, 'Where on $y = x^3$ is the point of inflection?', '{"choices":["(1, 1)","(0, 0)","(−1, −1)","None"],"answer":1}', '[]', 'Concave down for $x < 0$ and up for $x > 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5205b18b9614b7', 'les_cfcb6437796557', 4, 'review', 'multiple_choice', 3, 'A car''s speed is increasing at a decreasing rate. Which describes its distance-time graph at that time?', '{"choices":["Increasing, concave up","Increasing, concave down","Decreasing","Constant"],"answer":0}', '["Speed is the rate of change of distance."]', 'Distance increases, and its rate (speed) is increasing: concave up. (The speed graph itself is concave down.)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e4ff0e38e6f9e3', 'subj_math', 'rate-of-change', 'Average rate of change', 'The change in output divided by the change in input over an interval.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cfcb6437796557', (SELECT id FROM concepts WHERE slug = 'rate-of-change'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d968886662d4b4', 'subj_math', 'concavity', 'Concavity', 'Whether a function''s rate of change is increasing (concave up) or decreasing (concave down).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cfcb6437796557', (SELECT id FROM concepts WHERE slug = 'concavity'));

-- Lesson: complex-polar-form
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ea4ee24de8fe1c', 'complex-polar-form', 'Complex numbers in polar form', 'Plot complex numbers in the complex plane, find modulus and argument, convert between rectangular and polar form, and multiply and divide in polar form.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5ccf7f710f82c9', 'les_ea4ee24de8fe1c', 1, 'Plot a + bi in the complex plane and find its modulus and argument.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6d5709176578f2', 'les_ea4ee24de8fe1c', 2, 'Convert between a + bi and r(cos θ + i sin θ).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dfae180d780045', 'les_ea4ee24de8fe1c', 3, 'Multiply and divide complex numbers in polar form.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ccf7f710f82c9', 'les_ea4ee24de8fe1c', 'learn', 1, 'text', '{"body":"Plot $a + bi$ at the point $(a, b)$: real part horizontal, imaginary part vertical. Then describe it like a polar point: its distance from 0 and its angle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d5709176578f2', 'les_ea4ee24de8fe1c', 'learn', 2, 'definition', '{"term":"Polar form","body":"$z = a + bi = r(\\cos\\theta + i\\sin\\theta)$, where the modulus is $r = |z| = \\sqrt{a^2 + b^2}$ and the argument $\\theta$ satisfies $\\tan\\theta = \\frac{b}{a}$ (in the correct quadrant)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dfae180d780045', 'les_ea4ee24de8fe1c', 'learn', 3, 'definition', '{"term":"Multiplying and dividing","body":"$z_1z_2 = r_1r_2[\\cos(\\theta_1 + \\theta_2) + i\\sin(\\theta_1 + \\theta_2)]$: multiply moduli, add arguments. $\\frac{z_1}{z_2} = \\frac{r_1}{r_2}[\\cos(\\theta_1 - \\theta_2) + i\\sin(\\theta_1 - \\theta_2)]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2490a5ca2c07cf', 'les_ea4ee24de8fe1c', 'learn', 4, 'worked_example', '{"title":"Write $-1 + i\\sqrt{3}$ in polar form","steps":[{"latex":"r = \\sqrt{1 + 3} = 2","explanation":""},{"latex":"\\theta = \\tfrac{2\\pi}{3}","explanation":"Quadrant II, reference angle π/3."},{"latex":"2\\left(\\cos\\tfrac{2\\pi}{3} + i\\sin\\tfrac{2\\pi}{3}\\right)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e4829fbb08a56', 'les_ea4ee24de8fe1c', 'learn', 5, 'callout', '{"tone":"tip","title":"Multiplying by i is a rotation","body":"$i = \\cos\\frac{\\pi}{2} + i\\sin\\frac{\\pi}{2}$, so multiplying by $i$ rotates any complex number $90^\\circ$ counterclockwise without changing its length."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eaa1756d66c6cd', 'les_ea4ee24de8fe1c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electrical engineers write AC voltages as phasors $r\\angle\\theta$, and multiplying phasors (adding angles) is how circuit impedances combine."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ccf7f710f82c9', 'les_ea4ee24de8fe1c', 1, 'practice', 'numeric', 1, 'Find the modulus of $3 - 4i$.', '{"answer":5}', '[]', '5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6d5709176578f2', 'les_ea4ee24de8fe1c', 2, 'practice', 'short_text', 2, 'Write $2i$ in polar form. Use the format 2(cos(pi/2)+isin(pi/2)).', '{"accept":["2(cos(pi/2)+isin(pi/2))","2(cosπ/2+isinπ/2)"]}', '[]', '$r = 2$, $\theta = \frac{\pi}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dfae180d780045', 'les_ea4ee24de8fe1c', 3, 'practice', 'numeric', 2, '$z_1$ has modulus 3 and argument 40°; $z_2$ has modulus 5 and argument 70°. What is the argument of $z_1 z_2$ in degrees?', '{"answer":110,"unit":"°"}', '[]', '$40 + 70 = 110^\circ$ (and modulus 15).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2490a5ca2c07cf', 'les_ea4ee24de8fe1c', 4, 'review', 'short_text', 3, 'Convert $4(\cos\frac{\pi}{6} + i\sin\frac{\pi}{6})$ to $a + bi$ form. Use the format 2sqrt(3)+2i.', '{"accept":["2sqrt(3)+2i","2√3+2i"]}', '[]', '$4 \cdot \frac{\sqrt{3}}{2} + 4 \cdot \frac{1}{2}i = 2\sqrt{3} + 2i$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ea4ee24de8fe1c', (SELECT id FROM concepts WHERE slug = 'complex-numbers'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ea4ee24de8fe1c', (SELECT id FROM formulas WHERE slug = 'de-moivre'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ea4ee24de8fe1c', (SELECT id FROM formulas WHERE slug = 'polar-conversion'), 2);

-- Lesson: continuity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1d074decbcdb94', 'continuity', 'Continuity', 'Define continuity at a point with three conditions, classify removable, jump and infinite discontinuities, and apply the Intermediate Value Theorem.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_279c569d0775c3', 'les_1d074decbcdb94', 1, 'State the three conditions for continuity at x = a.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0b970f33ee5e5', 'les_1d074decbcdb94', 2, 'Classify discontinuities as removable, jump or infinite.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_79e011f028d0d0', 'les_1d074decbcdb94', 3, 'Make a piecewise function continuous and use the Intermediate Value Theorem to show a zero exists.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_279c569d0775c3', 'les_1d074decbcdb94', 'learn', 1, 'definition', '{"term":"Continuity at a point","body":"$f$ is continuous at $a$ if (1) $f(a)$ is defined, (2) $\\lim_{x \\to a} f(x)$ exists, and (3) they are equal. Informally: you can draw the graph through $a$ without lifting your pencil."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0b970f33ee5e5', 'les_1d074decbcdb94', 'learn', 2, 'definition', '{"term":"Types of discontinuity","body":"Removable: the limit exists but doesn''t equal $f(a)$ (a hole). Jump: the one-sided limits differ. Infinite: the function grows without bound (a vertical asymptote)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_79e011f028d0d0', 'les_1d074decbcdb94', 'learn', 3, 'worked_example', '{"title":"Find $k$ so that $f(x) = \\begin{cases} x^2 + 1, & x < 2 \\\\ kx - 1, & x \\ge 2 \\end{cases}$ is continuous","steps":[{"latex":"\\lim_{x \\to 2^-} = 5,\\quad f(2) = 2k - 1","explanation":""},{"latex":"2k - 1 = 5 \\Rightarrow k = 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_165224750e28dc', 'les_1d074decbcdb94', 'learn', 4, 'definition', '{"term":"Intermediate Value Theorem","body":"If $f$ is continuous on $[a, b]$ and $N$ is between $f(a)$ and $f(b)$, then $f(c) = N$ for some $c$ in $(a, b)$. In particular, a sign change guarantees a zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f98cb1721d538', 'les_1d074decbcdb94', 'learn', 5, 'worked_example', '{"title":"Show $x^3 + x - 1 = 0$ has a solution between 0 and 1","steps":[{"latex":"f(0) = -1,\\ f(1) = 1","explanation":"Polynomials are continuous; the sign changes."},{"latex":"\\text{by the IVT, a zero lies in } (0, 1)","explanation":"It''s about 0.682."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02a589af95311d', 'les_1d074decbcdb94', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Root-finding algorithms (bisection) rely on the IVT, and physical quantities like temperature are modeled as continuous: to go from 10° to 20°, it must pass through 15°."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_279c569d0775c3', 'les_1d074decbcdb94', 1, 'practice', 'multiple_choice', 1, '$f(x) = \frac{x^2 - 1}{x - 1}$ has what kind of discontinuity at $x = 1$?', '{"choices":["Removable","Jump","Infinite","None"],"answer":0}', '[]', 'The limit is 2 but $f(1)$ is undefined: a hole.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0b970f33ee5e5', 'les_1d074decbcdb94', 2, 'practice', 'multiple_choice', 2, '$g(x) = \frac{1}{(x - 3)^2}$ has what kind of discontinuity at $x = 3$?', '{"choices":["Removable","Jump","Infinite","None"],"answer":2}', '[]', 'A vertical asymptote.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_79e011f028d0d0', 'les_1d074decbcdb94', 3, 'practice', 'numeric', 2, 'Find $k$ so that $f(x) = \begin{cases} 2x + k, & x < 1 \\ 4 - x, & x \ge 1 \end{cases}$ is continuous.', '{"answer":1}', '["$2 + k = 3$."]', '$k = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_165224750e28dc', 'les_1d074decbcdb94', 4, 'review', 'multiple_choice', 3, '$f$ is continuous on $[1, 5]$ with $f(1) = -2$ and $f(5) = 6$. Which must be true?', '{"choices":["f(3) = 2","f(c) = 0 for some c in (1, 5)","f is increasing","f(c) = 7 for some c in (1, 5)"],"answer":1}', '[]', '0 is between −2 and 6, so by the IVT some $c$ gives $f(c) = 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1d074decbcdb94', 'subj_math', 'continuity', 'Continuity', 'A function is continuous at a when its limit there equals its value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1d074decbcdb94', (SELECT id FROM concepts WHERE slug = 'continuity'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function approaches as the input approaches a point.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1d074decbcdb94', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: de-moivres-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0eade46cddfd24', 'de-moivres-theorem', 'De Moivre''s Theorem', 'Raise complex numbers to powers with De Moivre''s Theorem and find all nth roots of a complex number.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a5374cbb43a916', 'les_0eade46cddfd24', 1, 'Use De Moivre''s Theorem to compute powers of complex numbers.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10f2ed29dc55da', 'les_0eade46cddfd24', 2, 'Find the n distinct nth roots of a complex number.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d4831415fbb04e', 'les_0eade46cddfd24', 3, 'Describe the roots geometrically as vertices of a regular polygon.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a5374cbb43a916', 'les_0eade46cddfd24', 'learn', 1, 'definition', '{"term":"De Moivre''s Theorem","body":"$[r(\\cos\\theta + i\\sin\\theta)]^n = r^n(\\cos n\\theta + i\\sin n\\theta)$. It follows from multiplying in polar form $n$ times."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10f2ed29dc55da', 'les_0eade46cddfd24', 'learn', 2, 'worked_example', '{"title":"Compute $(1 + i)^8$","steps":[{"latex":"1 + i = \\sqrt{2}\\left(\\cos\\tfrac{\\pi}{4} + i\\sin\\tfrac{\\pi}{4}\\right)","explanation":""},{"latex":"(\\sqrt{2})^8(\\cos 2\\pi + i\\sin 2\\pi) = 16","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4831415fbb04e', 'les_0eade46cddfd24', 'learn', 3, 'definition', '{"term":"nth roots","body":"The $n$ nth roots of $r(\\cos\\theta + i\\sin\\theta)$ are $\\sqrt[n]{r}\\left[\\cos\\frac{\\theta + 2\\pi k}{n} + i\\sin\\frac{\\theta + 2\\pi k}{n}\\right]$ for $k = 0, 1, \\dots, n - 1$. They''re evenly spaced around a circle, forming a regular $n$-gon."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b1d92ed1f0239', 'les_0eade46cddfd24', 'learn', 4, 'worked_example', '{"title":"Find the cube roots of $8$","steps":[{"latex":"8 = 8(\\cos 0 + i\\sin 0)","explanation":""},{"latex":"2\\left(\\cos\\tfrac{2\\pi k}{3} + i\\sin\\tfrac{2\\pi k}{3}\\right),\\ k = 0, 1, 2","explanation":""},{"latex":"2,\\ -1 + i\\sqrt{3},\\ -1 - i\\sqrt{3}","explanation":"An equilateral triangle of points."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab5e4f413dfa27', 'les_0eade46cddfd24', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Roots of unity are central to the Fast Fourier Transform, the algorithm behind audio compression, image processing and fast multiplication of huge numbers."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a5374cbb43a916', 'les_0eade46cddfd24', 1, 'practice', 'numeric', 2, 'Compute the modulus of $(1 + i\sqrt{3})^5$.', '{"answer":32}', '["$|1 + i\\sqrt{3}| = 2$."]', '$2^5 = 32$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10f2ed29dc55da', 'les_0eade46cddfd24', 2, 'practice', 'multiple_choice', 2, 'What is $i^{100}$ by De Moivre?', '{"choices":["1","i","−1","−i"],"answer":0}', '["$\\cos(50\\pi) + i\\sin(50\\pi)$."]', '$50\pi$ is a multiple of $2\pi$: 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d4831415fbb04e', 'les_0eade46cddfd24', 3, 'practice', 'numeric', 2, 'How many distinct fifth roots does any nonzero complex number have?', '{"answer":5}', '[]', '5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b1d92ed1f0239', 'les_0eade46cddfd24', 4, 'review', 'short_text', 3, 'Find the square roots of $i$. Use the format ±(sqrt(2)/2+sqrt(2)/2i).', '{"accept":["±(sqrt(2)/2+sqrt(2)/2i)","±(√2/2+√2/2i)"]}', '["$i = \\cos\\frac{\\pi}{2} + i\\sin\\frac{\\pi}{2}$; halve the angle."]', '$\pm\left(\frac{\sqrt{2}}{2} + \frac{\sqrt{2}}{2}i\right)$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0eade46cddfd24', (SELECT id FROM concepts WHERE slug = 'complex-numbers'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0eade46cddfd24', (SELECT id FROM formulas WHERE slug = 'de-moivre'), 1);

-- Lesson: dot-product
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f9a7e179f86ddf', 'dot-product', 'The dot product', 'Compute dot products, find the angle between vectors, test for orthogonality, find projections and compute work.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ded0f955b544eb', 'les_f9a7e179f86ddf', 1, 'Compute u · v from components.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_925bf8973f9f12', 'les_f9a7e179f86ddf', 2, 'Find the angle between two vectors and test for orthogonality.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ebe4ef05ebed3c', 'les_f9a7e179f86ddf', 3, 'Find the projection of one vector onto another and compute work W = F · d.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ded0f955b544eb', 'les_f9a7e179f86ddf', 'learn', 1, 'definition', '{"term":"Dot product","body":"$\\mathbf{u}\\cdot\\mathbf{v} = u_1v_1 + u_2v_2$, a number (scalar). Geometrically, $\\mathbf{u}\\cdot\\mathbf{v} = |\\mathbf{u}||\\mathbf{v}|\\cos\\theta$, so $\\cos\\theta = \\frac{\\mathbf{u}\\cdot\\mathbf{v}}{|\\mathbf{u}||\\mathbf{v}|}$. Vectors are orthogonal exactly when $\\mathbf{u}\\cdot\\mathbf{v} = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_925bf8973f9f12', 'les_f9a7e179f86ddf', 'experiment', 2, 'activity', '{"activity":"vectors","title":"Watch the dot product and angle","params":{"ux":4,"uy":0,"vx":2,"vy":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ebe4ef05ebed3c', 'les_f9a7e179f86ddf', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"Switch to \"Dot product\" view. Rotate v until the dot product is 0: the angle reads 90°. When is the dot product negative?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3360951c47c28', 'les_f9a7e179f86ddf', 'learn', 4, 'worked_example', '{"title":"Find the angle between $\\langle 2, 1 \\rangle$ and $\\langle -1, 3 \\rangle$","steps":[{"latex":"\\mathbf{u}\\cdot\\mathbf{v} = -2 + 3 = 1","explanation":""},{"latex":"\\cos\\theta = \\frac{1}{\\sqrt{5}\\sqrt{10}} = \\frac{1}{\\sqrt{50}} \\approx 0.1414","explanation":""},{"latex":"\\theta \\approx 81.9^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_767e257d5b28a6', 'les_f9a7e179f86ddf', 'learn', 5, 'definition', '{"term":"Projection and work","body":"The projection of $\\mathbf{v}$ onto $\\mathbf{u}$ is $\\text{proj}_{\\mathbf{u}}\\mathbf{v} = \\frac{\\mathbf{u}\\cdot\\mathbf{v}}{|\\mathbf{u}|^2}\\mathbf{u}$. Work done by a constant force $\\mathbf{F}$ along displacement $\\mathbf{d}$ is $W = \\mathbf{F}\\cdot\\mathbf{d}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e724b99294e7d4', 'les_f9a7e179f86ddf', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Work in physics, lighting calculations in 3D graphics (brightness depends on the angle between light and surface), and similarity scores in search engines all use dot products."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ded0f955b544eb', 'les_f9a7e179f86ddf', 1, 'practice', 'numeric', 1, 'Compute $\langle 3, -2 \rangle \cdot \langle 4, 5 \rangle$.', '{"answer":2}', '[]', '$12 - 10 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_925bf8973f9f12', 'les_f9a7e179f86ddf', 2, 'practice', 'multiple_choice', 2, 'Which pair is orthogonal?', '{"choices":["$\\langle 1, 2 \\rangle, \\langle 2, 1 \\rangle$","$\\langle 3, -6 \\rangle, \\langle 4, 2 \\rangle$","$\\langle 1, 1 \\rangle, \\langle 1, 2 \\rangle$","$\\langle 0, 1 \\rangle, \\langle 1, 1 \\rangle$"],"answer":1}', '[]', '$12 - 12 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ebe4ef05ebed3c', 'les_f9a7e179f86ddf', 3, 'practice', 'numeric', 2, 'Find the angle between $\langle 1, 0 \rangle$ and $\langle 1, 1 \rangle$ in degrees.', '{"answer":45,"unit":"°"}', '[]', '$\cos\theta = \frac{1}{\sqrt{2}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b3360951c47c28', 'les_f9a7e179f86ddf', 4, 'review', 'numeric', 3, 'A 20 N force $\mathbf{F} = \langle 16, 12 \rangle$ moves an object along $\mathbf{d} = \langle 5, 0 \rangle$ meters. How much work is done, in joules?', '{"answer":80,"unit":"J"}', '[]', '$16 \cdot 5 + 12 \cdot 0 = 80$ J.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7291eb9f68564d', 'subj_math', 'vectors', 'Vectors', 'Quantities with magnitude and direction, written in components.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f9a7e179f86ddf', (SELECT id FROM concepts WHERE slug = 'vectors'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f9a7e179f86ddf', (SELECT id FROM formulas WHERE slug = 'dot-product'), 1);

-- Lesson: double-angle-formulas
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a02478bb48e5af', 'double-angle-formulas', 'Double-angle formulas', 'Derive the double-angle formulas from the sum formulas, use the three forms of cos 2θ, and find exact values and simplify expressions, including half-angle formulas.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6a417100feceab', 'les_a02478bb48e5af', 1, 'Derive sin 2θ and cos 2θ from the sum formulas.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f4046a16280b0', 'les_a02478bb48e5af', 2, 'Use the three forms of cos 2θ and the power-reducing and half-angle formulas.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0964350b68f663', 'les_a02478bb48e5af', 3, 'Find exact values of sin 2θ and cos 2θ given one trig value and a quadrant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a417100feceab', 'les_a02478bb48e5af', 'learn', 1, 'definition', '{"term":"Double-angle formulas","body":"Set $B = A$ in the sum formulas: $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$; $\\cos 2\\theta = \\cos^2\\theta - \\sin^2\\theta = 2\\cos^2\\theta - 1 = 1 - 2\\sin^2\\theta$; $\\tan 2\\theta = \\frac{2\\tan\\theta}{1 - \\tan^2\\theta}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f4046a16280b0', 'les_a02478bb48e5af', 'learn', 2, 'definition', '{"term":"Power-reducing and half-angle","body":"Solving the cosine forms: $\\cos^2\\theta = \\frac{1 + \\cos 2\\theta}{2}$ and $\\sin^2\\theta = \\frac{1 - \\cos 2\\theta}{2}$. So $\\sin\\frac{\\theta}{2} = \\pm\\sqrt{\\frac{1 - \\cos\\theta}{2}}$, with the sign set by the quadrant of $\\frac{\\theta}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0964350b68f663', 'les_a02478bb48e5af', 'learn', 3, 'worked_example', '{"title":"$\\sin\\theta = \\tfrac{4}{5}$, $\\theta$ in Quadrant II. Find $\\sin 2\\theta$ and $\\cos 2\\theta$.","steps":[{"latex":"\\cos\\theta = -\\tfrac{3}{5}","explanation":""},{"latex":"\\sin 2\\theta = 2\\left(\\tfrac{4}{5}\\right)\\left(-\\tfrac{3}{5}\\right) = -\\tfrac{24}{25}","explanation":""},{"latex":"\\cos 2\\theta = \\tfrac{9}{25} - \\tfrac{16}{25} = -\\tfrac{7}{25}","explanation":"Check: $\\left(\\frac{24}{25}\\right)^2 + \\left(\\frac{7}{25}\\right)^2 = 1$. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a72d968e319a0', 'les_a02478bb48e5af', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"A projectile''s range $R = \\frac{v^2\\sin 2\\theta}{g}$ uses a double angle; it''s largest when $2\\theta = 90^\\circ$, so a $45^\\circ$ launch goes farthest (ignoring air resistance)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a417100feceab', 'les_a02478bb48e5af', 1, 'practice', 'multiple_choice', 1, 'Which equals $2\sin 15^\circ\cos 15^\circ$?', '{"choices":["$\\sin 30^\\circ$","$\\cos 30^\\circ$","$\\sin 15^\\circ$","$2\\sin 30^\\circ$"],"answer":0}', '[]', '$\sin 30^\circ = \frac{1}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f4046a16280b0', 'les_a02478bb48e5af', 2, 'practice', 'short_text', 2, '$\cos\theta = \frac{5}{13}$, θ in Quadrant I. Find $\sin 2\theta$.', '{"accept":["120/169"]}', '["$\\sin\\theta = \\frac{12}{13}$."]', '$2 \cdot \frac{12}{13} \cdot \frac{5}{13} = \frac{120}{169}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0964350b68f663', 'les_a02478bb48e5af', 3, 'practice', 'short_text', 2, 'With the same θ, find $\cos 2\theta$.', '{"accept":["-119/169"]}', '[]', '$\frac{25 - 144}{169} = -\frac{119}{169}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4a72d968e319a0', 'les_a02478bb48e5af', 4, 'review', 'multiple_choice', 3, 'Simplify $1 - 2\sin^2(3x)$.', '{"choices":["$\\cos 6x$","$\\cos 3x$","$\\sin 6x$","$\\cos^2 3x$"],"answer":0}', '[]', '$\cos(2 \cdot 3x)$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a02478bb48e5af', (SELECT id FROM concepts WHERE slug = 'trig-identities'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a02478bb48e5af', (SELECT id FROM formulas WHERE slug = 'trig-identities'), 1);

-- Lesson: ellipses
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6cd5fa3efa53b5', 'ellipses', 'Ellipses', 'Define an ellipse by its foci, write and graph its standard equation, find vertices, foci and eccentricity, and convert from general form.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa578becbab44a', 'les_6cd5fa3efa53b5', 1, 'Define an ellipse as the set of points whose distances to two foci sum to a constant.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c28e695f26aaf9', 'les_6cd5fa3efa53b5', 2, 'Graph an ellipse from its standard form and find its center, vertices, co-vertices and foci.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ca426b0cd7ac52', 'les_6cd5fa3efa53b5', 3, 'Find eccentricity and write equations from given features.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa578becbab44a', 'les_6cd5fa3efa53b5', 'learn', 1, 'definition', '{"term":"Ellipse","body":"The set of points $P$ with $PF_1 + PF_2 = 2a$ for two fixed foci. Standard form (horizontal major axis): $\\frac{(x - h)^2}{a^2} + \\frac{(y - k)^2}{b^2} = 1$ with $a > b$, vertices $(h \\pm a, k)$, co-vertices $(h, k \\pm b)$, foci $(h \\pm c, k)$ where $c^2 = a^2 - b^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c28e695f26aaf9', 'les_6cd5fa3efa53b5', 'experiment', 2, 'activity', '{"activity":"conics","title":"Stretch an ellipse","params":{"kind":"ellipse","a":5,"b":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca426b0cd7ac52', 'les_6cd5fa3efa53b5', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"With $a = 5$, $b = 3$, the foci are at $\\pm 4$ because $c^2 = 25 - 9 = 16$. Make $b$ equal to $a$: the foci merge at the center and the ellipse becomes a circle (eccentricity 0)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6335cdf13efda6', 'les_6cd5fa3efa53b5', 'learn', 4, 'worked_example', '{"title":"Graph $\\dfrac{x^2}{9} + \\dfrac{(y - 2)^2}{25} = 1$","steps":[{"latex":"a^2 = 25 \\text{ under } y \\Rightarrow \\text{vertical major axis}","explanation":"The larger denominator decides the major axis."},{"latex":"\\text{center } (0, 2),\\ \\text{vertices } (0, 7), (0, -3)","explanation":""},{"latex":"c = \\sqrt{25 - 9} = 4 \\Rightarrow \\text{foci } (0, 6), (0, -2)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab99d2a54c679b', 'les_6cd5fa3efa53b5', 'learn', 5, 'definition', '{"term":"Eccentricity","body":"$e = \\frac{c}{a}$, between 0 (circle) and 1 (very flat). Earth''s orbit has $e \\approx 0.017$, nearly circular."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84ba7db21f3d01', 'les_6cd5fa3efa53b5', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Planets orbit the Sun in ellipses with the Sun at one focus (Kepler''s first law). Whispering galleries and kidney-stone lithotripters use the reflective property: sound or waves from one focus converge at the other."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa578becbab44a', 'les_6cd5fa3efa53b5', 1, 'practice', 'numeric', 1, 'For $\frac{x^2}{36} + \frac{y^2}{20} = 1$, find $c$.', '{"answer":4}', '["$c^2 = 36 - 20$."]', '$c = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c28e695f26aaf9', 'les_6cd5fa3efa53b5', 2, 'practice', 'short_text', 2, 'What are the vertices of $\frac{x^2}{36} + \frac{y^2}{20} = 1$? Enter like (-6,0),(6,0).', '{"accept":["(-6,0),(6,0)"]}', '[]', '$(\pm 6, 0)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca426b0cd7ac52', 'les_6cd5fa3efa53b5', 3, 'practice', 'short_text', 2, 'Write the ellipse centered at the origin with vertices $(\pm 5, 0)$ and foci $(\pm 3, 0)$. Use the format x^2/25+y^2/16=1.', '{"accept":["x^2/25+y^2/16=1"]}', '["$b^2 = 25 - 9$."]', '$\frac{x^2}{25} + \frac{y^2}{16} = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6335cdf13efda6', 'les_6cd5fa3efa53b5', 4, 'review', 'numeric', 3, 'Find the eccentricity of $\frac{x^2}{100} + \frac{y^2}{64} = 1$.', '{"answer":0.6}', '["$c = 6$, $a = 10$."]', '$0.6$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_18d95b5dccb0ea', 'subj_math', 'conic-sections', 'Conic sections', 'Curves from slicing a cone: circles, ellipses, parabolas and hyperbolas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6cd5fa3efa53b5', (SELECT id FROM concepts WHERE slug = 'conic-sections'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6cd5fa3efa53b5', (SELECT id FROM formulas WHERE slug = 'conic-equations'), 1);

-- Lesson: evaluating-limits-algebraically
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d3ec9a922d2a30', 'evaluating-limits-algebraically', 'Evaluating limits algebraically', 'Evaluate limits by direct substitution, factoring, rationalizing and simplifying complex fractions, and find limits at infinity of rational functions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5db3571186513', 'les_d3ec9a922d2a30', 1, 'Use limit laws and direct substitution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b1e08486db8aec', 'les_d3ec9a922d2a30', 2, 'Resolve 0/0 forms by factoring, rationalizing or simplifying.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_266fdaa688166f', 'les_d3ec9a922d2a30', 3, 'Find limits at infinity of rational functions by comparing degrees.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5db3571186513', 'les_d3ec9a922d2a30', 'learn', 1, 'definition', '{"term":"Direct substitution","body":"If $f$ is a polynomial, or a rational function defined at $a$, then $\\lim_{x \\to a} f(x) = f(a)$. If substitution gives $\\frac{0}{0}$, the limit may still exist: simplify first."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1e08486db8aec', 'les_d3ec9a922d2a30', 'learn', 2, 'worked_example', '{"title":"$\\lim_{x \\to 3} \\dfrac{x^2 - 9}{x^2 - 3x}$","steps":[{"latex":"\\frac{(x - 3)(x + 3)}{x(x - 3)} = \\frac{x + 3}{x}","explanation":"Factor and cancel."},{"latex":"\\to \\tfrac{6}{3} = 2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_266fdaa688166f', 'les_d3ec9a922d2a30', 'learn', 3, 'worked_example', '{"title":"$\\lim_{x \\to 0} \\dfrac{\\sqrt{x + 9} - 3}{x}$","steps":[{"latex":"\\frac{(\\sqrt{x + 9} - 3)(\\sqrt{x + 9} + 3)}{x(\\sqrt{x + 9} + 3)} = \\frac{1}{\\sqrt{x + 9} + 3}","explanation":"Multiply by the conjugate."},{"latex":"\\to \\tfrac{1}{6}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_859f506f70b525', 'les_d3ec9a922d2a30', 'learn', 4, 'definition', '{"term":"Limits at infinity","body":"For a rational function, compare degrees: numerator lower → 0; equal → ratio of leading coefficients; numerator higher → the function grows without bound. These match horizontal asymptotes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a88dbda061657', 'les_d3ec9a922d2a30', 'learn', 5, 'worked_example', '{"title":"$\\lim_{x \\to \\infty} \\dfrac{4x^2 - x}{2x^2 + 5}$","steps":[{"latex":"= \\tfrac{4}{2} = 2","explanation":"Equal degrees."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_730ba78ebb5e1d', 'les_d3ec9a922d2a30', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"The derivative is defined as a limit of difference quotients, which almost always start as 0/0 and need exactly these algebraic tricks."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5db3571186513', 'les_d3ec9a922d2a30', 1, 'practice', 'numeric', 1, 'Evaluate $\lim_{x \to 2} (x^3 - 4x + 1)$.', '{"answer":1}', '[]', '$8 - 8 + 1 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1e08486db8aec', 'les_d3ec9a922d2a30', 2, 'practice', 'numeric', 2, 'Evaluate $\lim_{x \to -4} \dfrac{x^2 + 7x + 12}{x + 4}$.', '{"answer":-1}', '["$(x + 3)(x + 4)$."]', '$x + 3 \to -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_266fdaa688166f', 'les_d3ec9a922d2a30', 3, 'practice', 'numeric', 2, 'Evaluate $\lim_{x \to 4} \dfrac{\sqrt{x} - 2}{x - 4}$. Enter a decimal.', '{"answer":0.25}', '["Rationalize the numerator."]', '$\frac{1}{\sqrt{x} + 2} \to \frac{1}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_859f506f70b525', 'les_d3ec9a922d2a30', 4, 'practice', 'numeric', 2, 'Evaluate $\lim_{x \to \infty} \dfrac{3x + 1}{x^2 - 2}$.', '{"answer":0}', '[]', 'Numerator degree lower: 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4a88dbda061657', 'les_d3ec9a922d2a30', 5, 'review', 'short_text', 3, 'Evaluate $\lim_{h \to 0} \dfrac{(2 + h)^2 - 4}{h}$.', '{"accept":["4"]}', '["$\\frac{4h + h^2}{h} = 4 + h$."]', '4. (This is the slope of $x^2$ at $x = 2$.)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function approaches as the input approaches a point.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d3ec9a922d2a30', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: even-odd-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5c7045d094234f', 'even-odd-functions', 'Even and odd functions', 'Test functions algebraically and graphically for even and odd symmetry, and use symmetry to complete graphs and simplify work.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_126645474d1fa0', 'les_5c7045d094234f', 1, 'Define even and odd functions algebraically.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a5a76ffa3d2b6d', 'les_5c7045d094234f', 2, 'Test a function by computing f(−x).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bf9d5a4ec376a2', 'les_5c7045d094234f', 3, 'Relate even and odd functions to y-axis and origin symmetry.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_126645474d1fa0', 'les_5c7045d094234f', 'learn', 1, 'definition', '{"term":"Even and odd","body":"$f$ is even if $f(-x) = f(x)$ for all $x$ in its domain: its graph is symmetric about the y-axis. $f$ is odd if $f(-x) = -f(x)$: its graph is symmetric about the origin (a $180^\\circ$ rotation maps it to itself). Most functions are neither."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a5a76ffa3d2b6d', 'les_5c7045d094234f', 'learn', 2, 'worked_example', '{"title":"Classify $f(x) = x^4 - 3x^2$, $g(x) = x^3 + x$, $h(x) = x^2 + x$","steps":[{"latex":"f(-x) = x^4 - 3x^2 = f(x)","explanation":"Even."},{"latex":"g(-x) = -x^3 - x = -g(x)","explanation":"Odd."},{"latex":"h(-x) = x^2 - x","explanation":"Neither: not h(x) and not −h(x)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf9d5a4ec376a2', 'les_5c7045d094234f', 'learn', 3, 'callout', '{"tone":"tip","title":"Power shortcut","body":"A polynomial with only even powers (including constants) is even; with only odd powers, it''s odd. $\\cos x$ is even and $\\sin x$, $\\tan x$ are odd."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02e9b35d76ad43', 'les_5c7045d094234f', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Symmetry halves the work in calculus (integrals of odd functions over $[-a, a]$ are 0) and in physics and signal processing, where signals split into even and odd parts."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_126645474d1fa0', 'les_5c7045d094234f', 1, 'practice', 'multiple_choice', 1, 'Which function is even?', '{"choices":["$x^5$","$x^2 + 7$","$x^3 - x$","$2x + 1$"],"answer":1}', '[]', 'Only even powers.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a5a76ffa3d2b6d', 'les_5c7045d094234f', 2, 'practice', 'multiple_choice', 2, 'Classify $f(x) = \frac{x}{x^2 + 1}$.', '{"choices":["Even","Odd","Neither","Both"],"answer":1}', '["Compute $f(-x)$."]', '$f(-x) = \frac{-x}{x^2 + 1} = -f(x)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf9d5a4ec376a2', 'les_5c7045d094234f', 3, 'practice', 'multiple_choice', 2, 'An odd function has $f(3) = 7$. What is $f(-3)$?', '{"choices":["7","−7","3","Cannot tell"],"answer":1}', '[]', '$f(-3) = -f(3) = -7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_02e9b35d76ad43', 'les_5c7045d094234f', 4, 'review', 'multiple_choice', 3, 'Which is true of every odd function defined at 0?', '{"choices":["$f(0) = 1$","$f(0) = 0$","f(0) is undefined","Nothing"],"answer":1}', '["$f(0) = -f(0)$."]', 'Only 0 equals its own negative.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d4ff0b45b75340', 'subj_math', 'function-symmetry', 'Even and odd functions', 'f(−x) = f(x) (y-axis symmetry) or f(−x) = −f(x) (origin symmetry).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5c7045d094234f', (SELECT id FROM concepts WHERE slug = 'function-symmetry'));

-- Lesson: exponential-manipulation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4dd4d22e4ed0a8', 'exponential-manipulation', 'Exponential functions and manipulation', 'Rewrite exponential expressions to reveal horizontal shifts, vertical stretches and different time units, using the properties of exponents.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_292c0ff7e2480e', 'les_4dd4d22e4ed0a8', 1, 'Show that a horizontal shift of an exponential is a vertical dilation: b^(x + k) = b^k · b^x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e084c46b909303', 'les_4dd4d22e4ed0a8', 2, 'Rewrite growth rates for different time units, such as yearly to monthly.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4dc9cc20f67500', 'les_4dd4d22e4ed0a8', 3, 'Use negative and rational exponents to rewrite exponential expressions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_292c0ff7e2480e', 'les_4dd4d22e4ed0a8', 'learn', 1, 'definition', '{"term":"Shift = stretch","body":"$b^{x + k} = b^k \\cdot b^x$. So shifting $y = b^x$ left by $k$ is the same as stretching it vertically by $b^k$. Example: $2^{x + 3} = 8 \\cdot 2^x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e084c46b909303', 'les_4dd4d22e4ed0a8', 'learn', 2, 'definition', '{"term":"Changing time units","body":"A quantity that grows by factor $b$ per year grows by $b^{1/12}$ per month, since $(b^{1/12})^{12} = b$. And $b^{x/k} = (b^{1/k})^x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4dc9cc20f67500', 'les_4dd4d22e4ed0a8', 'learn', 3, 'worked_example', '{"title":"A population triples every 5 years: $P = 200 \\cdot 3^{t/5}$. What is the yearly growth factor?","steps":[{"latex":"3^{t/5} = (3^{1/5})^t","explanation":""},{"latex":"3^{1/5} \\approx 1.2457","explanation":"About 24.6% growth per year."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9b4297140445d1', 'les_4dd4d22e4ed0a8', 'learn', 4, 'worked_example', '{"title":"Rewrite $f(x) = 5 \\cdot 4^{x - 1}$ in the form $a \\cdot b^x$","steps":[{"latex":"5 \\cdot 4^{-1} \\cdot 4^x = 1.25 \\cdot 4^x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_325d3c9243467e', 'les_4dd4d22e4ed0a8', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Banks quote annual rates but compound monthly; drug labels give half-lives in hours while doses are daily. Rewriting exponentials converts between these units."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_292c0ff7e2480e', 'les_4dd4d22e4ed0a8', 1, 'practice', 'short_text', 1, 'Rewrite $3^{x + 2}$ in the form a·3^x. Use the format 9*3^x.', '{"accept":["9*3^x","9·3^x","9(3^x)"]}', '[]', '$3^2 \cdot 3^x = 9 \cdot 3^x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e084c46b909303', 'les_4dd4d22e4ed0a8', 2, 'practice', 'multiple_choice', 2, 'Which is equivalent to $2^{-x}$?', '{"choices":["$-2^x$","$\\left(\\frac{1}{2}\\right)^x$","$2^{1/x}$","$-\\frac{1}{2^x}$"],"answer":1}', '[]', '$2^{-x} = (2^{-1})^x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4dc9cc20f67500', 'les_4dd4d22e4ed0a8', 3, 'practice', 'short_text', 2, 'A quantity grows 10% per year. Write its monthly growth factor as a power of 1.1. Use the format 1.1^(1/12).', '{"accept":["1.1^(1/12)"]}', '[]', '$1.1^{1/12} \approx 1.008$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9b4297140445d1', 'les_4dd4d22e4ed0a8', 4, 'review', 'multiple_choice', 3, '$f(x) = 16 \cdot 2^x$ is a horizontal shift of $2^x$ by…', '{"choices":["4 left","4 right","16 left","16 up"],"answer":0}', '["$16 = 2^4$."]', '$2^{x + 4}$: 4 units left.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4dd4d22e4ed0a8', (SELECT id FROM concepts WHERE slug = 'exponential-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4dd4d22e4ed0a8', (SELECT id FROM formulas WHERE slug = 'exponent-rules'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4dd4d22e4ed0a8', (SELECT id FROM formulas WHERE slug = 'exponential-function'), 2);

-- Lesson: function-model-selection
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_55428d450e24c3', 'function-model-selection', 'Function model selection and assumption articulation', 'Choose linear, quadratic, polynomial, exponential, logarithmic, rational or sinusoidal models from data patterns and context, and state the assumptions and limits of each model.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ca1a680ff750b9', 'les_55428d450e24c3', 1, 'Select a function type from patterns in data (differences, ratios, periodicity, asymptotes).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_be91c2c2f0469d', 'les_55428d450e24c3', 2, 'Justify a model choice using the context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2e85d0fc6fbe56', 'les_55428d450e24c3', 3, 'State the assumptions behind a model and the domain where it''s reasonable.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca1a680ff750b9', 'les_55428d450e24c3', 'learn', 1, 'definition', '{"term":"Clues for choosing a model","body":"Constant differences → linear. Constant second differences → quadratic. Constant ratios → exponential. Rapid early change that levels off with no bound → logarithmic. Repeating cycles → sinusoidal. Behavior near a forbidden value or a leveling-off value → rational."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be91c2c2f0469d', 'les_55428d450e24c3', 'learn', 2, 'worked_example', '{"title":"A savings account earns a fixed percent each year","steps":[{"latex":"\\text{constant ratio of balances}","explanation":"Exponential model."},{"latex":"\\text{assumption: the rate never changes and no withdrawals}","explanation":"State assumptions explicitly."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e85d0fc6fbe56', 'les_55428d450e24c3', 'learn', 3, 'worked_example', '{"title":"Hours of daylight over a year in Chicago","steps":[{"latex":"\\text{repeats every 365 days}","explanation":"Sinusoidal model."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a6d32c50b2257f', 'les_55428d450e24c3', 'learn', 4, 'callout', '{"tone":"warning","title":"Every model has a domain","body":"A linear model of a child''s height breaks down at adulthood; an exponential model of a population ignores limited resources. Say where the model applies."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4a970e0957b50', 'les_55428d450e24c3', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scientists, economists and engineers choose models by matching data patterns and the mechanism behind the data, then check residuals to see if the model fits."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca1a680ff750b9', 'les_55428d450e24c3', 1, 'practice', 'multiple_choice', 1, 'Data have outputs that double each step. Which model fits?', '{"choices":["Linear","Quadratic","Exponential","Sinusoidal"],"answer":2}', '[]', 'Constant ratio.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be91c2c2f0469d', 'les_55428d450e24c3', 2, 'practice', 'multiple_choice', 2, 'The height of a point on a spinning wheel over time is best modeled by…', '{"choices":["Linear","Exponential","Sinusoidal","Logarithmic"],"answer":2}', '[]', 'It repeats periodically.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2e85d0fc6fbe56', 'les_55428d450e24c3', 3, 'practice', 'multiple_choice', 2, 'The perceived loudness of a sound grows quickly at low intensities and slowly at high ones, without bound. Which model?', '{"choices":["Logarithmic","Exponential","Quadratic","Rational"],"answer":0}', '[]', 'That''s the logarithmic pattern (the decibel scale).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a6d32c50b2257f', 'les_55428d450e24c3', 4, 'review', 'multiple_choice', 3, 'A linear model predicts a car''s value falls 2,000 dollars per year from 20,000. What''s an unstated assumption?', '{"choices":["The car is red","Depreciation is constant each year and value never goes below 0","The car appreciates","Prices are exponential"],"answer":1}', '[]', 'A linear model assumes a constant rate, and it only makes sense up to year 10.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_55428d450e24c3', (SELECT id FROM concepts WHERE slug = 'function-families'));

-- Lesson: fundamental-identities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_32636cef49ce4b', 'fundamental-identities', 'Fundamental identities', 'Use reciprocal, quotient, Pythagorean, even-odd and cofunction identities to simplify expressions and verify identities.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_643c421ba8a3f6', 'les_32636cef49ce4b', 1, 'State the reciprocal, quotient, Pythagorean, even-odd and cofunction identities.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fbc91dee1639c2', 'les_32636cef49ce4b', 2, 'Simplify trigonometric expressions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a62d25525b8bbb', 'les_32636cef49ce4b', 3, 'Verify identities by transforming one side into the other.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_643c421ba8a3f6', 'les_32636cef49ce4b', 'learn', 1, 'definition', '{"term":"Core identities","body":"Reciprocal: $\\csc\\theta = \\frac{1}{\\sin\\theta}$, $\\sec\\theta = \\frac{1}{\\cos\\theta}$, $\\cot\\theta = \\frac{1}{\\tan\\theta}$. Quotient: $\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta}$. Pythagorean: $\\sin^2\\theta + \\cos^2\\theta = 1$, $1 + \\tan^2\\theta = \\sec^2\\theta$, $1 + \\cot^2\\theta = \\csc^2\\theta$. Even-odd: $\\cos(-\\theta) = \\cos\\theta$, $\\sin(-\\theta) = -\\sin\\theta$. Cofunction: $\\sin\\left(\\frac{\\pi}{2} - \\theta\\right) = \\cos\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbc91dee1639c2', 'les_32636cef49ce4b', 'learn', 2, 'worked_example', '{"title":"Simplify $\\dfrac{\\sec\\theta - \\cos\\theta}{\\tan\\theta}$","steps":[{"latex":"\\frac{\\frac{1}{\\cos\\theta} - \\cos\\theta}{\\tan\\theta} = \\frac{\\frac{1 - \\cos^2\\theta}{\\cos\\theta}}{\\frac{\\sin\\theta}{\\cos\\theta}}","explanation":""},{"latex":"= \\frac{\\sin^2\\theta}{\\sin\\theta} = \\sin\\theta","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a62d25525b8bbb', 'les_32636cef49ce4b', 'learn', 3, 'worked_example', '{"title":"Verify $\\dfrac{1}{1 - \\sin x} + \\dfrac{1}{1 + \\sin x} = 2\\sec^2 x$","steps":[{"latex":"\\frac{(1 + \\sin x) + (1 - \\sin x)}{1 - \\sin^2 x}","explanation":"Common denominator."},{"latex":"= \\frac{2}{\\cos^2 x} = 2\\sec^2 x","explanation":"∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a87b49676d4c7d', 'les_32636cef49ce4b', 'learn', 4, 'callout', '{"tone":"tip","title":"Strategies","body":"Work on the more complicated side. Rewrite everything in sines and cosines. Combine fractions. Look for $1 - \\sin^2 x$ and similar Pythagorean patterns. Never move terms across the equals sign; transform one side only."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_461e46cd1ec309', 'les_32636cef49ce4b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Identities simplify formulas in physics and engineering and are essential in calculus for integrals involving trig functions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_643c421ba8a3f6', 'les_32636cef49ce4b', 1, 'practice', 'multiple_choice', 1, 'Simplify $\tan\theta\cos\theta$.', '{"choices":["$\\sin\\theta$","$\\cos\\theta$","$1$","$\\sec\\theta$"],"answer":0}', '[]', '$\frac{\sin\theta}{\cos\theta}\cos\theta = \sin\theta$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbc91dee1639c2', 'les_32636cef49ce4b', 2, 'practice', 'multiple_choice', 2, 'Simplify $\sec^2 x - \tan^2 x$.', '{"choices":["0","1","$\\sec x$","$-1$"],"answer":1}', '[]', 'From $1 + \tan^2 x = \sec^2 x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a62d25525b8bbb', 'les_32636cef49ce4b', 3, 'practice', 'short_text', 2, 'Simplify $\sin(-x)\csc x$. Enter a number.', '{"accept":["-1"]}', '[]', '$-\sin x \cdot \frac{1}{\sin x} = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a87b49676d4c7d', 'les_32636cef49ce4b', 4, 'review', 'multiple_choice', 3, 'Simplify $\frac{\cos^2 x}{1 - \sin x}$.', '{"choices":["$1 - \\sin x$","$1 + \\sin x$","$\\cos x$","$\\sin x$"],"answer":1}', '["$\\cos^2 x = (1 - \\sin x)(1 + \\sin x)$."]', '$1 + \sin x$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_32636cef49ce4b', (SELECT id FROM concepts WHERE slug = 'trig-identities'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_32636cef49ce4b', (SELECT id FROM formulas WHERE slug = 'pythagorean-identity'), 1);

-- Lesson: hyperbolas
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_730d3e610bd458', 'hyperbolas', 'Hyperbolas', 'Define a hyperbola by its foci, graph it from standard form with its asymptotes, and find vertices, foci and eccentricity.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_acd07b4f908824', 'les_730d3e610bd458', 1, 'Define a hyperbola as the set of points whose distances to two foci differ by a constant.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_48b45ecef57829', 'les_730d3e610bd458', 2, 'Graph a hyperbola using its vertices and the asymptote box.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ea7ac4213db4ac', 'les_730d3e610bd458', 3, 'Find foci, asymptotes and eccentricity, and write equations from features.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_acd07b4f908824', 'les_730d3e610bd458', 'learn', 1, 'definition', '{"term":"Hyperbola","body":"The set of points with $|PF_1 - PF_2| = 2a$. Standard form opening left-right: $\\frac{(x - h)^2}{a^2} - \\frac{(y - k)^2}{b^2} = 1$; vertices $(h \\pm a, k)$, foci $(h \\pm c, k)$ with $c^2 = a^2 + b^2$, asymptotes $y - k = \\pm\\frac{b}{a}(x - h)$. If the $y$-term is positive, it opens up-down."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_48b45ecef57829', 'les_730d3e610bd458', 'experiment', 2, 'activity', '{"activity":"conics","title":"Shape a hyperbola","params":{"kind":"hyperbola","a":3,"b":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ea7ac4213db4ac', 'les_730d3e610bd458', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"The dashed asymptotes have slopes $\\pm\\frac{b}{a}$. Increase $b$: the branches open wider. Notice the foci are always farther out than the vertices, since $c > a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97cbff847ec927', 'les_730d3e610bd458', 'learn', 4, 'worked_example', '{"title":"Graph $\\dfrac{x^2}{16} - \\dfrac{y^2}{9} = 1$","steps":[{"latex":"a = 4,\\ b = 3","explanation":""},{"latex":"\\text{vertices } (\\pm 4, 0);\\ c = 5 \\Rightarrow \\text{foci } (\\pm 5, 0)","explanation":""},{"latex":"\\text{asymptotes } y = \\pm\\tfrac{3}{4}x","explanation":"Draw the 8-by-6 box; the asymptotes are its diagonals."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80c415fd800140', 'les_730d3e610bd458', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"LORAN navigation located ships on hyperbolas from time differences of radio signals; some comets follow hyperbolic paths; cooling towers have hyperboloid shapes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_acd07b4f908824', 'les_730d3e610bd458', 1, 'practice', 'numeric', 1, 'For $\frac{x^2}{9} - \frac{y^2}{16} = 1$, find $c$.', '{"answer":5}', '[]', '$\sqrt{9 + 16} = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_48b45ecef57829', 'les_730d3e610bd458', 2, 'practice', 'short_text', 2, 'Find the asymptotes of $\frac{x^2}{9} - \frac{y^2}{16} = 1$. Use the format y=±4x/3.', '{"accept":["y=±4x/3","y=±(4/3)x"]}', '[]', '$y = \pm\frac{4}{3}x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ea7ac4213db4ac', 'les_730d3e610bd458', 3, 'practice', 'short_text', 2, 'Does $\frac{y^2}{4} - \frac{x^2}{25} = 1$ open left-right or up-down? Enter "up-down" or "left-right".', '{"accept":["up-down","updown"]}', '[]', 'The $y^2$ term is positive: up-down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97cbff847ec927', 'les_730d3e610bd458', 4, 'review', 'numeric', 3, 'Find the eccentricity of $\frac{x^2}{16} - \frac{y^2}{9} = 1$.', '{"answer":1.25}', '["$e = c / a$."]', '$5 / 4 = 1.25$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_18d95b5dccb0ea', 'subj_math', 'conic-sections', 'Conic sections', 'Curves from slicing a cone: circles, ellipses, parabolas and hyperbolas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_730d3e610bd458', (SELECT id FROM concepts WHERE slug = 'conic-sections'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_730d3e610bd458', (SELECT id FROM formulas WHERE slug = 'conic-equations'), 1);

-- Lesson: inverse-trig-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1f64c563ab76ba', 'inverse-trig-functions', 'Inverse trigonometric functions', 'Define arcsine, arccosine and arctangent on restricted domains, evaluate them exactly and with a calculator, and evaluate compositions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3a89a05d1ab6ba', 'les_1f64c563ab76ba', 1, 'Explain why sine, cosine and tangent need restricted domains to have inverses.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_22e9a6cef7fc14', 'les_1f64c563ab76ba', 2, 'Evaluate inverse trig functions, giving answers in the correct range.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b12579d261998c', 'les_1f64c563ab76ba', 3, 'Evaluate compositions such as sin(arccos x) using right triangles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a89a05d1ab6ba', 'les_1f64c563ab76ba', 'learn', 1, 'definition', '{"term":"Restricted ranges","body":"$\\sin^{-1} x$ (arcsin) returns an angle in $\\left[-\\frac{\\pi}{2}, \\frac{\\pi}{2}\\right]$ for $x \\in [-1, 1]$. $\\cos^{-1} x$ returns an angle in $[0, \\pi]$. $\\tan^{-1} x$ returns an angle in $\\left(-\\frac{\\pi}{2}, \\frac{\\pi}{2}\\right)$ for any real $x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22e9a6cef7fc14', 'les_1f64c563ab76ba', 'learn', 2, 'worked_example', '{"title":"Evaluate $\\sin^{-1}\\left(-\\tfrac{1}{2}\\right)$, $\\cos^{-1}\\left(-\\tfrac{\\sqrt{2}}{2}\\right)$, $\\tan^{-1}\\sqrt{3}$","steps":[{"latex":"-\\tfrac{\\pi}{6}","explanation":"In [−π/2, π/2]: not 7π/6."},{"latex":"\\tfrac{3\\pi}{4}","explanation":"In [0, π]."},{"latex":"\\tfrac{\\pi}{3}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b12579d261998c', 'les_1f64c563ab76ba', 'learn', 3, 'worked_example', '{"title":"Evaluate $\\sin\\left(\\cos^{-1}\\tfrac{3}{5}\\right)$","steps":[{"latex":"\\theta = \\cos^{-1}\\tfrac{3}{5},\\ \\text{adj } 3,\\ \\text{hyp } 5","explanation":"θ is in Quadrant I."},{"latex":"\\text{opp} = 4 \\Rightarrow \\sin\\theta = \\tfrac{4}{5}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f0a5d55b36835', 'les_1f64c563ab76ba', 'learn', 4, 'callout', '{"tone":"warning","title":"sin(sin⁻¹ x) vs sin⁻¹(sin x)","body":"$\\sin(\\sin^{-1} x) = x$ for $x \\in [-1, 1]$, but $\\sin^{-1}(\\sin x) = x$ only for $x \\in \\left[-\\frac{\\pi}{2}, \\frac{\\pi}{2}\\right]$. For example $\\sin^{-1}(\\sin \\pi) = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26c3f8343d1c67', 'les_1f64c563ab76ba', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Navigation and robotics compute headings with arctangent (often atan2), and surveying finds angles from measured lengths."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a89a05d1ab6ba', 'les_1f64c563ab76ba', 1, 'practice', 'short_text', 1, 'Evaluate $\cos^{-1} 0$. Use the format pi/2.', '{"accept":["pi/2","π/2"]}', '[]', '$\frac{\pi}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22e9a6cef7fc14', 'les_1f64c563ab76ba', 2, 'practice', 'short_text', 2, 'Evaluate $\sin^{-1}\left(\frac{\sqrt{3}}{2}\right)$. Use the format pi/3.', '{"accept":["pi/3","π/3"]}', '[]', '$\frac{\pi}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b12579d261998c', 'les_1f64c563ab76ba', 3, 'practice', 'multiple_choice', 2, 'What is $\tan^{-1}(-1)$?', '{"choices":["$\\frac{3\\pi}{4}$","$-\\frac{\\pi}{4}$","$\\frac{7\\pi}{4}$","$\\frac{\\pi}{4}$"],"answer":1}', '["The range is (−π/2, π/2)."]', '$-\frac{\pi}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f0a5d55b36835', 'les_1f64c563ab76ba', 4, 'practice', 'short_text', 2, 'Evaluate $\cos\left(\tan^{-1}\frac{5}{12}\right)$. Enter a fraction.', '{"accept":["12/13"]}', '[]', 'Opp 5, adj 12, hyp 13: $\frac{12}{13}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26c3f8343d1c67', 'les_1f64c563ab76ba', 5, 'review', 'numeric', 3, 'Evaluate $\sin^{-1}(\sin\frac{5\pi}{6})$ as a decimal multiple of π (for π/6, enter 0.1667).', '{"answer":0.16666666666666666,"tolerance":0.001}', '["$\\sin\\frac{5\\pi}{6} = \\frac{1}{2}$."]', '$\sin^{-1}\frac{1}{2} = \frac{\pi}{6}$, not $\frac{5\pi}{6}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1f64c563ab76ba', (SELECT id FROM concepts WHERE slug = 'inverse-trig'));

-- Lesson: inverses-exponential-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_efd88e30251a7f', 'inverses-exponential-functions', 'Inverses of exponential functions', 'Find inverses of transformed exponential functions, which are logarithmic functions, and compare their domains, ranges, asymptotes and rates of change.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_360c41064664cc', 'les_efd88e30251a7f', 1, 'Find the inverse of f(x) = a·b^x + k algebraically.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_678fdb5c1c735b', 'les_efd88e30251a7f', 2, 'Relate the domain, range and asymptote of an exponential to those of its inverse logarithm.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c9220ef6d024f', 'les_efd88e30251a7f', 3, 'Compare how exponentials and logarithms change over equal-length intervals.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_360c41064664cc', 'les_efd88e30251a7f', 'learn', 1, 'text', '{"body":"Because exponentials are one-to-one, every exponential function has an inverse, and that inverse is a logarithmic function. The exponential''s horizontal asymptote becomes the log''s vertical asymptote."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_678fdb5c1c735b', 'les_efd88e30251a7f', 'learn', 2, 'worked_example', '{"title":"Find the inverse of $f(x) = 3 \\cdot 2^x - 5$","steps":[{"latex":"x = 3 \\cdot 2^y - 5","explanation":"Swap x and y."},{"latex":"\\tfrac{x + 5}{3} = 2^y \\Rightarrow y = \\log_2\\tfrac{x + 5}{3}","explanation":""},{"latex":"f^{-1}(x) = \\log_2\\tfrac{x + 5}{3},\\ x > -5","explanation":"f has range $y > -5$ (asymptote $y = -5$), so $f^{-1}$ has domain $x > -5$ (asymptote $x = -5$)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c9220ef6d024f', 'les_efd88e30251a7f', 'experiment', 3, 'activity', '{"activity":"exp-log","title":"Asymptotes swap under inversion","params":{"b":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60b277886fcc35', 'les_efd88e30251a7f', 'experiment', 4, 'callout', '{"tone":"tip","title":"Compare growth","body":"Over equal input steps, an exponential''s outputs change by equal factors, while a logarithm''s outputs change by equal amounts over equal input factors: $\\log_2 x$ goes up by 1 each time $x$ doubles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e7d2e7d395bb9', 'les_efd88e30251a7f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"If a model says a quantity is $f(t) = 100e^{0.05t}$, its inverse $t = 20\\ln\\frac{f}{100}$ answers \"when will it reach this level?\""}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_360c41064664cc', 'les_efd88e30251a7f', 1, 'practice', 'short_text', 2, 'Find the inverse of $f(x) = 5^x$. Use the format log_5(x).', '{"accept":["log_5(x)","log5(x)","log_5x"]}', '[]', '$\log_5 x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_678fdb5c1c735b', 'les_efd88e30251a7f', 2, 'practice', 'short_text', 2, 'Find the inverse of $f(x) = e^x + 2$. Use the format ln(x-2).', '{"accept":["ln(x-2)"]}', '[]', '$x = e^y + 2$, so $y = \ln(x - 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c9220ef6d024f', 'les_efd88e30251a7f', 3, 'practice', 'multiple_choice', 2, '$f(x) = 4^x - 3$ has horizontal asymptote $y = -3$. What is the vertical asymptote of $f^{-1}$?', '{"choices":["$x = 3$","$x = -3$","$y = -3$","$x = 4$"],"answer":1}', '[]', 'Swapping coordinates: $x = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60b277886fcc35', 'les_efd88e30251a7f', 4, 'review', 'multiple_choice', 3, 'As $x$ goes from 1 to 2 to 4 to 8, $\log_2 x$ goes…', '{"choices":["up by 1 each time","doubles each time","up by 2 each time","stays the same"],"answer":0}', '[]', '0, 1, 2, 3: equal increases over equal factors.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_efd88e30251a7f', (SELECT id FROM concepts WHERE slug = 'logarithms'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_efd88e30251a7f', (SELECT id FROM concepts WHERE slug = 'inverse-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_efd88e30251a7f', (SELECT id FROM formulas WHERE slug = 'log-properties'), 1);

-- Lesson: limits-graphs-tables
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_04e4cfcff5d1e0', 'limits-graphs-tables', 'Limits from graphs and tables', 'Estimate limits from tables of values and graphs, use one-sided limits, and recognize when a limit does not exist.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d0e52c1153e2c', 'les_04e4cfcff5d1e0', 1, 'Explain the meaning of lim f(x) = L as x approaches a.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_99d7adcda8f063', 'les_04e4cfcff5d1e0', 2, 'Estimate limits numerically and graphically, including at holes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68331fde777d9d', 'les_04e4cfcff5d1e0', 3, 'Use one-sided limits and identify limits that do not exist.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d0e52c1153e2c', 'les_04e4cfcff5d1e0', 'learn', 1, 'definition', '{"term":"Limit","body":"$\\lim_{x \\to a} f(x) = L$ means $f(x)$ can be made as close to $L$ as we like by taking $x$ close enough to $a$ (but not equal to $a$). The value $f(a)$ itself doesn''t matter, and may not even exist."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_99d7adcda8f063', 'les_04e4cfcff5d1e0', 'learn', 2, 'worked_example', '{"title":"Estimate $\\lim_{x \\to 2} \\dfrac{x^2 - 4}{x - 2}$ from a table","steps":[{"latex":"x = 1.9, 1.99, 1.999: \\ f = 3.9, 3.99, 3.999","explanation":""},{"latex":"x = 2.1, 2.01, 2.001: \\ f = 4.1, 4.01, 4.001","explanation":""},{"latex":"\\text{limit } = 4","explanation":"f(2) is undefined (0/0), but algebra agrees: $\\frac{(x - 2)(x + 2)}{x - 2} = x + 2 \\to 4$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68331fde777d9d', 'les_04e4cfcff5d1e0', 'learn', 3, 'definition', '{"term":"One-sided limits","body":"$\\lim_{x \\to a^-}$ approaches from the left, $\\lim_{x \\to a^+}$ from the right. The two-sided limit exists exactly when both one-sided limits exist and are equal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2598e3c483b74', 'les_04e4cfcff5d1e0', 'learn', 4, 'worked_example', '{"title":"$f(x) = \\frac{|x|}{x}$ near 0","steps":[{"latex":"\\lim_{x \\to 0^-} = -1,\\ \\lim_{x \\to 0^+} = 1","explanation":""},{"latex":"\\lim_{x \\to 0} f(x) \\text{ does not exist}","explanation":"The one-sided limits differ (a jump)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_896c85ab24cad2', 'les_04e4cfcff5d1e0', 'experiment', 5, 'activity', '{"activity":"rational-graph","title":"Limits near an asymptote","params":{"a":1,"h":0,"k":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f16ad06bd9b534', 'les_04e4cfcff5d1e0', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"For $y = \\frac{1}{x}$, the graph shoots up on the right of 0 and down on the left. Neither one-sided limit is a number, so $\\lim_{x \\to 0} \\frac{1}{x}$ does not exist. But as $x \\to \\infty$, the graph approaches 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7fe3644dddb418', 'les_04e4cfcff5d1e0', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Limits are the foundation of calculus: instantaneous speed and the area under curves are both defined as limits."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d0e52c1153e2c', 'les_04e4cfcff5d1e0', 1, 'practice', 'numeric', 1, 'Estimate $\lim_{x \to 3} (2x + 1)$.', '{"answer":7}', '[]', '7.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_99d7adcda8f063', 'les_04e4cfcff5d1e0', 2, 'practice', 'numeric', 2, 'Find $\lim_{x \to 1} \dfrac{x^2 - 1}{x - 1}$.', '{"answer":2}', '[]', '$x + 1 \to 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68331fde777d9d', 'les_04e4cfcff5d1e0', 3, 'practice', 'multiple_choice', 2, '$\lim_{x \to 2^-} f(x) = 5$ and $\lim_{x \to 2^+} f(x) = 5$, and $f(2) = 8$. What is $\lim_{x \to 2} f(x)$?', '{"choices":["5","8","Does not exist","13"],"answer":0}', '[]', 'Both sides approach 5; the value at 2 doesn''t affect the limit.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d2598e3c483b74', 'les_04e4cfcff5d1e0', 4, 'review', 'multiple_choice', 3, 'What is $\lim_{x \to 0} \sin\left(\frac{1}{x}\right)$?', '{"choices":["0","1","Does not exist","∞"],"answer":2}', '["The function oscillates infinitely often near 0."]', 'It oscillates between −1 and 1 without settling, so the limit does not exist.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function approaches as the input approaches a point.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_04e4cfcff5d1e0', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: matrices-transformations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e7f7d32fa0edb5', 'matrices-transformations', 'Matrices as transformations of the plane', 'Represent reflections, rotations, dilations and shears as 2 × 2 matrices, compose them by multiplication, and interpret the determinant as an area factor.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_83fbb8e53eeac0', 'les_e7f7d32fa0edb5', 1, 'Apply a 2 × 2 matrix to points and figures.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c1edb0a1d4db38', 'les_e7f7d32fa0edb5', 2, 'Write matrices for reflections, rotations and dilations, using where i and j go.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_80bd5fa37f2f5c', 'les_e7f7d32fa0edb5', 3, 'Compose transformations by multiplying matrices and interpret the determinant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83fbb8e53eeac0', 'les_e7f7d32fa0edb5', 'learn', 1, 'definition', '{"term":"Matrix as a function","body":"A 2 × 2 matrix $A$ sends the point (column vector) $\\begin{bmatrix} x \\\\ y \\end{bmatrix}$ to $A\\begin{bmatrix} x \\\\ y \\end{bmatrix}$. Its first column is where $\\langle 1, 0 \\rangle$ goes and its second column is where $\\langle 0, 1 \\rangle$ goes, so you can build any linear transformation from those two images."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1edb0a1d4db38', 'les_e7f7d32fa0edb5', 'learn', 2, 'definition', '{"term":"Standard matrices","body":"Rotation by $\\theta$: $\\begin{bmatrix} \\cos\\theta & -\\sin\\theta \\\\ \\sin\\theta & \\cos\\theta \\end{bmatrix}$. Reflection over the x-axis: $\\begin{bmatrix} 1 & 0 \\\\ 0 & -1 \\end{bmatrix}$. Over $y = x$: $\\begin{bmatrix} 0 & 1 \\\\ 1 & 0 \\end{bmatrix}$. Dilation by $k$: $\\begin{bmatrix} k & 0 \\\\ 0 & k \\end{bmatrix}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80bd5fa37f2f5c', 'les_e7f7d32fa0edb5', 'experiment', 3, 'activity', '{"activity":"transformations","title":"The same transformations as matrices","params":{"kind":"rotate"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb7feaa29bfb92', 'les_e7f7d32fa0edb5', 'learn', 4, 'worked_example', '{"title":"Rotate $(3, 1)$ by $90^\\circ$ with a matrix","steps":[{"latex":"\\begin{bmatrix} 0 & -1 \\\\ 1 & 0 \\end{bmatrix}\\begin{bmatrix} 3 \\\\ 1 \\end{bmatrix} = \\begin{bmatrix} -1 \\\\ 3 \\end{bmatrix}","explanation":"Matches the rule $(x, y) \\to (-y, x)$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_574dbc854c98c7', 'les_e7f7d32fa0edb5', 'learn', 5, 'worked_example', '{"title":"Reflect over the x-axis, then rotate $90^\\circ$. Find the single matrix.","steps":[{"latex":"R \\cdot F = \\begin{bmatrix} 0 & -1 \\\\ 1 & 0 \\end{bmatrix}\\begin{bmatrix} 1 & 0 \\\\ 0 & -1 \\end{bmatrix} = \\begin{bmatrix} 0 & 1 \\\\ 1 & 0 \\end{bmatrix}","explanation":"The first transformation goes on the right."},{"latex":"\\text{reflection over } y = x","explanation":"Composition of two transformations is one."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4aec9a065ecdbb', 'les_e7f7d32fa0edb5', 'learn', 6, 'callout', '{"tone":"note","title":"Determinant","body":"$|\\det A|$ is the factor by which areas are multiplied; a negative determinant means orientation is reversed (as with reflections). Rotations have determinant 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9dd1e279854086', 'les_e7f7d32fa0edb5', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every 2D and 3D graphics pipeline, from games to CAD, transforms points with matrices, composing many transformations into one matrix for speed."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_83fbb8e53eeac0', 'les_e7f7d32fa0edb5', 1, 'practice', 'short_text', 1, 'Apply $\begin{bmatrix} 2 & 0 \\ 0 & 2 \end{bmatrix}$ to $(4, -1)$. Enter as (x,y).', '{"accept":["(8,-2)"]}', '[]', '$(8, -2)$: a dilation by 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c1edb0a1d4db38', 'les_e7f7d32fa0edb5', 2, 'practice', 'short_text', 2, 'Apply $\begin{bmatrix} 0 & 1 \\ 1 & 0 \end{bmatrix}$ to $(5, 2)$. Enter as (x,y).', '{"accept":["(2,5)"]}', '[]', 'Reflection over $y = x$: $(2, 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_80bd5fa37f2f5c', 'les_e7f7d32fa0edb5', 3, 'practice', 'multiple_choice', 2, 'What is the determinant of any rotation matrix?', '{"choices":["0","1","−1","It depends on θ"],"answer":1}', '["$\\cos^2\\theta + \\sin^2\\theta$."]', '1: rotations preserve area and orientation.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb7feaa29bfb92', 'les_e7f7d32fa0edb5', 4, 'review', 'short_text', 3, 'Find the matrix that rotates by $180^\circ$. Use the format [[-1,0],[0,-1]].', '{"accept":["[[-1,0],[0,-1]]"]}', '[]', '$\cos 180^\circ = -1$, $\sin 180^\circ = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e7f7d32fa0edb5', (SELECT id FROM concepts WHERE slug = 'matrices'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e7f7d32fa0edb5', (SELECT id FROM concepts WHERE slug = 'rigid-motions'));

-- Lesson: oblique-triangles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2c3d65fe84ac41', 'oblique-triangles', 'The Law of Sines and the Law of Cosines', 'Solve any triangle by choosing the Law of Sines or Law of Cosines from the given information, handle the ambiguous case, and compute areas.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b595d321e51f9c', 'les_2c3d65fe84ac41', 1, 'Choose the Law of Sines (AAS, ASA, SSA) or the Law of Cosines (SAS, SSS).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a939b9462173f0', 'les_2c3d65fe84ac41', 2, 'Solve oblique triangles, including the ambiguous SSA case.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f39c79772a7767', 'les_2c3d65fe84ac41', 3, 'Find triangle areas with ½ab sin C and Heron''s formula.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b595d321e51f9c', 'les_2c3d65fe84ac41', 'learn', 1, 'formula', '{"latex":"\\frac{\\sin A}{a} = \\frac{\\sin B}{b} = \\frac{\\sin C}{c}, \\qquad c^2 = a^2 + b^2 - 2ab\\cos C","title":"Laws of Sines and Cosines"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a939b9462173f0', 'les_2c3d65fe84ac41', 'learn', 2, 'text', '{"body":"Decision rule: if you know an angle and its opposite side, use the Law of Sines. If you know two sides and the included angle, or all three sides, use the Law of Cosines. With SSA, check for zero, one or two triangles (compare the given opposite side with $h = b\\sin A$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f39c79772a7767', 'les_2c3d65fe84ac41', 'learn', 3, 'worked_example', '{"title":"SAS: $b = 10$, $c = 7$, $A = 48^\\circ$. Solve the triangle.","steps":[{"latex":"a^2 = 100 + 49 - 140\\cos 48^\\circ \\approx 55.32 \\Rightarrow a \\approx 7.44","explanation":"Law of Cosines."},{"latex":"\\sin C = \\tfrac{7\\sin 48^\\circ}{7.44} \\approx 0.699 \\Rightarrow C \\approx 44.4^\\circ","explanation":"Find the smaller remaining angle first (opposite the shorter side), so it must be acute."},{"latex":"B \\approx 180 - 48 - 44.4 = 87.6^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c87962be41620a', 'les_2c3d65fe84ac41', 'learn', 4, 'worked_example', '{"title":"SSS: $a = 8$, $b = 5$, $c = 7$. Find angle C.","steps":[{"latex":"\\cos C = \\frac{64 + 25 - 49}{80} = 0.5 \\Rightarrow C = 60^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_daf3c45434c67c', 'les_2c3d65fe84ac41', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Surveyors, pilots and astronomers solve oblique triangles constantly: distances across lakes, flight paths with wind, and distances to nearby stars by parallax."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b595d321e51f9c', 'les_2c3d65fe84ac41', 1, 'practice', 'multiple_choice', 1, 'You know two sides and the included angle. Which law do you use first?', '{"choices":["Law of Sines","Law of Cosines","Pythagorean theorem","Either"],"answer":1}', '[]', 'SAS: Law of Cosines.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a939b9462173f0', 'les_2c3d65fe84ac41', 2, 'practice', 'numeric', 2, '$A = 30^\circ$, $B = 45^\circ$, $a = 10$. Find $b$ to the nearest hundredth.', '{"answer":14.14,"tolerance":0.006}', '["$b = \\frac{10\\sin 45^\\circ}{\\sin 30^\\circ}$."]', '$10\sqrt{2} \approx 14.14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f39c79772a7767', 'les_2c3d65fe84ac41', 3, 'practice', 'numeric', 2, 'Sides 9, 12, 15. Find the largest angle in degrees.', '{"answer":90,"unit":"°"}', '[]', '$\cos C = \frac{81 + 144 - 225}{216} = 0$, so $90^\circ$ (a 3-4-5 triangle).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c87962be41620a', 'les_2c3d65fe84ac41', 4, 'review', 'numeric', 3, 'Find the area of the triangle with $a = 6$, $b = 9$, $C = 120^\circ$, to the nearest tenth.', '{"answer":23.4,"tolerance":0.06}', '["$\\frac{1}{2}ab\\sin C$."]', '$27\sin 120^\circ = 27 \cdot 0.8660 \approx 23.4$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2c3d65fe84ac41', (SELECT id FROM concepts WHERE slug = 'law-of-sines'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2c3d65fe84ac41', (SELECT id FROM concepts WHERE slug = 'law-of-cosines'));

-- Lesson: parametric-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7123b3d56b50f9', 'parametric-equations', 'Parametric equations', 'Graph curves given by x(t) and y(t), eliminate the parameter, and model motion such as projectiles with parametric equations.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b69caa94c775f8', 'les_7123b3d56b50f9', 1, 'Graph a parametric curve and show its direction of motion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1b2e79fdb1c203', 'les_7123b3d56b50f9', 2, 'Eliminate the parameter to find a rectangular equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e411f0b407eb48', 'les_7123b3d56b50f9', 3, 'Model projectile motion and circular motion parametrically.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b69caa94c775f8', 'les_7123b3d56b50f9', 'learn', 1, 'definition', '{"term":"Parametric equations","body":"$x = f(t)$, $y = g(t)$ give a point for each value of the parameter $t$. As $t$ increases, the point traces a curve in a definite direction, so parametric equations describe where and when."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b2e79fdb1c203', 'les_7123b3d56b50f9', 'learn', 2, 'worked_example', '{"title":"Eliminate the parameter: $x = 2t + 1$, $y = t^2$","steps":[{"latex":"t = \\tfrac{x - 1}{2}","explanation":""},{"latex":"y = \\left(\\tfrac{x - 1}{2}\\right)^2","explanation":"A parabola traced left to right as t increases."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e411f0b407eb48', 'les_7123b3d56b50f9', 'learn', 3, 'worked_example', '{"title":"Eliminate the parameter: $x = 3\\cos t$, $y = 3\\sin t$, $0 \\le t < 2\\pi$","steps":[{"latex":"x^2 + y^2 = 9\\cos^2 t + 9\\sin^2 t = 9","explanation":"Pythagorean identity."},{"latex":"\\text{circle of radius 3, counterclockwise}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4e7279cb89ef49', 'les_7123b3d56b50f9', 'experiment', 4, 'activity', '{"activity":"projectile","title":"A projectile is a parametric curve"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce1e365fe34abc', 'les_7123b3d56b50f9', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The projectile''s position is $x = v\\cos\\theta \\cdot t$ and $y = v\\sin\\theta \\cdot t - \\frac{1}{2}gt^2$. Each moment $t$ gives one point; the readouts show the time of flight."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2cabc63168b4e6', 'les_7123b3d56b50f9', 'learn', 6, 'worked_example', '{"title":"A ball is kicked at 20 m/s at $30^\\circ$. When does it land?","steps":[{"latex":"y(t) = 10t - 4.9t^2","explanation":"$20\\sin 30^\\circ = 10$."},{"latex":"t(10 - 4.9t) = 0 \\Rightarrow t \\approx 2.04 \\text{ s}","explanation":""},{"latex":"x(2.04) = 20\\cos 30^\\circ \\cdot 2.04 \\approx 35.3 \\text{ m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a306870e821ebd', 'les_7123b3d56b50f9', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Animation paths, robot arm trajectories, planetary motion and the Bézier curves used in fonts and vector graphics are all parametric."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b69caa94c775f8', 'les_7123b3d56b50f9', 1, 'practice', 'short_text', 1, 'Eliminate the parameter: $x = t + 3$, $y = 2t$. Write y in terms of x.', '{"accept":["y=2x-6"]}', '[]', '$t = x - 3$, $y = 2x - 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b2e79fdb1c203', 'les_7123b3d56b50f9', 2, 'practice', 'multiple_choice', 2, '$x = \cos t$, $y = \sin t$ for $0 \le t \le \pi$ traces…', '{"choices":["a full circle","the upper half of the unit circle","a line","a parabola"],"answer":1}', '[]', '$y \ge 0$: the upper semicircle, from (1, 0) to (−1, 0).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e411f0b407eb48', 'les_7123b3d56b50f9', 3, 'practice', 'numeric', 2, 'For $x = 4t$, $y = 16t - 5t^2$, find the maximum height y.', '{"answer":12.8}', '["Vertex at $t = 1.6$."]', '$y(1.6) = 25.6 - 12.8 = 12.8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4e7279cb89ef49', 'les_7123b3d56b50f9', 4, 'review', 'numeric', 3, 'A projectile has $x = 30t$, $y = 40t - 4.9t^2$ (meters). How far horizontally does it travel before landing, to the nearest meter?', '{"answer":245,"unit":"m","tolerance":0.5}', '["Land when $t = 40/4.9$."]', '$t \approx 8.163$, so $x \approx 244.9 \approx 245$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7123b3d56b50f9', 'subj_math', 'parametric-equations', 'Parametric equations', 'Describing x and y separately as functions of a parameter, often time.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7123b3d56b50f9', (SELECT id FROM concepts WHERE slug = 'parametric-equations'));

-- Lesson: polar-coordinates
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_294f4a8f1a6964', 'polar-coordinates', 'Polar coordinates', 'Plot points in polar coordinates, convert points and equations between polar and rectangular form, and recognize that a point has many polar names.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fbcc65b411e67e', 'les_294f4a8f1a6964', 1, 'Plot (r, θ), including negative r.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cf1a268100b3b9', 'les_294f4a8f1a6964', 2, 'Convert points between polar and rectangular coordinates.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_efb3f76a463f0c', 'les_294f4a8f1a6964', 3, 'Convert simple equations between polar and rectangular form.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbcc65b411e67e', 'les_294f4a8f1a6964', 'learn', 1, 'definition', '{"term":"Polar coordinates","body":"$(r, \\theta)$ means: face direction $\\theta$ from the positive x-axis and go $r$ units (backwards if $r < 0$). Every point has infinitely many names: $(r, \\theta) = (r, \\theta + 2\\pi) = (-r, \\theta + \\pi)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf1a268100b3b9', 'les_294f4a8f1a6964', 'learn', 2, 'definition', '{"term":"Conversions","body":"$x = r\\cos\\theta$, $y = r\\sin\\theta$; $r^2 = x^2 + y^2$, $\\tan\\theta = \\frac{y}{x}$ (choose $\\theta$ in the right quadrant)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_efb3f76a463f0c', 'les_294f4a8f1a6964', 'learn', 3, 'worked_example', '{"title":"Convert $\\left(4, \\tfrac{2\\pi}{3}\\right)$ to rectangular and $(-3, 3)$ to polar","steps":[{"latex":"x = 4\\cos\\tfrac{2\\pi}{3} = -2,\\ y = 4\\sin\\tfrac{2\\pi}{3} = 2\\sqrt{3}","explanation":""},{"latex":"r = \\sqrt{18} = 3\\sqrt{2},\\ \\theta = \\tfrac{3\\pi}{4}","explanation":"Quadrant II, so not −π/4."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9907967e1695a9', 'les_294f4a8f1a6964', 'learn', 4, 'worked_example', '{"title":"Convert $r = 6\\sin\\theta$ to rectangular form","steps":[{"latex":"r^2 = 6r\\sin\\theta \\Rightarrow x^2 + y^2 = 6y","explanation":"Multiply both sides by r."},{"latex":"x^2 + (y - 3)^2 = 9","explanation":"A circle with center (0, 3) and radius 3."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9580b1a52753a0', 'les_294f4a8f1a6964', 'experiment', 5, 'activity', '{"activity":"polar-graph","title":"Trace a polar curve","params":{"kind":"circle","b":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3eb6a44fa2e12a', 'les_294f4a8f1a6964', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Radar, sonar and air traffic control report positions as distance and bearing; antenna radiation patterns and spiral galaxies are naturally described in polar form."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbcc65b411e67e', 'les_294f4a8f1a6964', 1, 'practice', 'short_text', 1, 'Convert $(2, \pi)$ to rectangular. Enter as (x,y).', '{"accept":["(-2,0)"]}', '[]', '$(-2, 0)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cf1a268100b3b9', 'les_294f4a8f1a6964', 2, 'practice', 'numeric', 2, 'Convert $(5, -5)$ to polar: find $r$ to two decimals.', '{"answer":7.07,"tolerance":0.006}', '[]', '$5\sqrt{2} \approx 7.07$, with $\theta = -\frac{\pi}{4}$ (or $\frac{7\pi}{4}$).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_efb3f76a463f0c', 'les_294f4a8f1a6964', 3, 'practice', 'multiple_choice', 2, 'Which is another name for $\left(3, \frac{\pi}{6}\right)$?', '{"choices":["$\\left(-3, \\frac{\\pi}{6}\\right)$","$\\left(-3, \\frac{7\\pi}{6}\\right)$","$\\left(3, -\\frac{\\pi}{6}\\right)$","$\\left(3, \\frac{7\\pi}{6}\\right)$"],"answer":1}', '["$(-r, \\theta + \\pi)$."]', '$\left(-3, \frac{7\pi}{6}\right)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9907967e1695a9', 'les_294f4a8f1a6964', 4, 'review', 'short_text', 3, 'Convert $r = 4$ to rectangular form.', '{"accept":["x^2+y^2=16"]}', '[]', 'A circle: $x^2 + y^2 = 16$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_294f4a8f1a6964', 'subj_math', 'polar-coordinates', 'Polar coordinates', 'Locating points by distance r from the pole and angle θ.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_294f4a8f1a6964', (SELECT id FROM concepts WHERE slug = 'polar-coordinates'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_294f4a8f1a6964', (SELECT id FROM formulas WHERE slug = 'polar-conversion'), 1);

-- Lesson: polar-equation-graphs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2526b7644a152c', 'polar-equation-graphs', 'Graphs of polar equations', 'Graph circles, limaçons, cardioids, roses and spirals in polar form, using symmetry, zeros and maximum r.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f3513c71d7f774', 'les_2526b7644a152c', 1, 'Graph polar equations by tables and by recognizing families.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ee981a1fb35c7f', 'les_2526b7644a152c', 2, 'Classify limaçons by comparing a and b, and count rose petals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8969d5cc40ab7c', 'les_2526b7644a152c', 3, 'Use symmetry tests and the maximum value of |r|.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3513c71d7f774', 'les_2526b7644a152c', 'learn', 1, 'definition', '{"term":"Families","body":"Circles: $r = a$, $r = 2a\\cos\\theta$, $r = 2a\\sin\\theta$. Limaçons $r = a + b\\cos\\theta$: inner loop if $a < b$, cardioid if $a = b$, dimpled if $b < a < 2b$, convex if $a \\ge 2b$. Roses $r = b\\cos(n\\theta)$: $n$ petals if $n$ is odd, $2n$ if even. Spiral of Archimedes: $r = c\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee981a1fb35c7f', 'les_2526b7644a152c', 'experiment', 2, 'activity', '{"activity":"polar-graph","title":"Explore the families","params":{"kind":"limacon","a":1,"b":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8969d5cc40ab7c', 'les_2526b7644a152c', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"Start with $a = 1$, $b = 2$ (inner loop) and raise $a$ to 2 (cardioid), 3 (dimpled), then 4 (convex). Switch to roses and compare $n = 3$ and $n = 4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a2d89e83e8c96', 'les_2526b7644a152c', 'learn', 4, 'worked_example', '{"title":"Describe $r = 3 + 3\\sin\\theta$","steps":[{"latex":"a = b = 3","explanation":"A cardioid."},{"latex":"\\text{symmetric about } \\theta = \\tfrac{\\pi}{2}","explanation":"Sine-based: vertical symmetry."},{"latex":"\\max r = 6 \\text{ at } \\theta = \\tfrac{\\pi}{2};\\ r = 0 \\text{ at } \\theta = \\tfrac{3\\pi}{2}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3793dd26796497', 'les_2526b7644a152c', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Microphone pickup patterns are cardioids, antennas have rose-like radiation lobes, and spirals describe shells, galaxies and record grooves."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3513c71d7f774', 'les_2526b7644a152c', 1, 'practice', 'numeric', 1, 'How many petals does $r = 5\cos(3\theta)$ have?', '{"answer":3}', '[]', 'Odd n: 3 petals.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ee981a1fb35c7f', 'les_2526b7644a152c', 2, 'practice', 'numeric', 2, 'How many petals does $r = 2\sin(4\theta)$ have?', '{"answer":8}', '[]', 'Even n: 8 petals.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8969d5cc40ab7c', 'les_2526b7644a152c', 3, 'practice', 'multiple_choice', 2, 'Classify $r = 2 + 5\cos\theta$.', '{"choices":["Cardioid","Limaçon with inner loop","Dimpled limaçon","Circle"],"answer":1}', '[]', '$a = 2 < b = 5$: inner loop.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7a2d89e83e8c96', 'les_2526b7644a152c', 4, 'review', 'numeric', 3, 'What is the maximum value of r for $r = 4 - 4\cos\theta$?', '{"answer":8}', '[]', 'At $\theta = \pi$: $4 + 4 = 8$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_294f4a8f1a6964', 'subj_math', 'polar-coordinates', 'Polar coordinates', 'Locating points by distance r from the pole and angle θ.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2526b7644a152c', (SELECT id FROM concepts WHERE slug = 'polar-coordinates'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2526b7644a152c', (SELECT id FROM formulas WHERE slug = 'polar-conversion'), 1);

-- Lesson: polynomial-rates-of-change
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a621103440d411', 'polynomial-rates-of-change', 'Polynomial functions and rates of change', 'Relate a polynomial''s increasing and decreasing intervals, extrema and concavity to its rate of change, and recognize constant nth differences for degree-n polynomials.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6b50ab98c4f10e', 'les_a621103440d411', 1, 'Identify local and global extrema of polynomials from graphs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7dd4874c6bc055', 'les_a621103440d411', 2, 'Connect where the rate of change changes sign to extrema, and where it changes direction to inflection points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8a9ae23ffabfc7', 'les_a621103440d411', 3, 'Recognize that a degree-n polynomial has constant nth differences over equal steps.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b50ab98c4f10e', 'les_a621103440d411', 'learn', 1, 'definition', '{"term":"Extrema and rates","body":"A local maximum occurs where the rate of change switches from positive to negative; a local minimum where it switches from negative to positive. A global (absolute) maximum or minimum is the greatest or least value on the whole domain. Polynomials of odd degree have no global extrema."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7dd4874c6bc055', 'les_a621103440d411', 'experiment', 2, 'activity', '{"activity":"polynomial-zeros","title":"Extrema and inflection","params":{"a":0.2,"r1":-3,"m1":1,"r2":0,"m2":1,"r3":3,"m3":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a9ae23ffabfc7', 'les_a621103440d411', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"This cubic, $0.2x(x + 3)(x - 3)$, has a local max and a local min and one inflection point between them, where the curve switches from concave down to concave up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cfc8d6fed4a54e', 'les_a621103440d411', 'learn', 4, 'worked_example', '{"title":"Cubic $y = x^3$ at $x$ = 0, 1, 2, 3, 4","steps":[{"latex":"y: 0, 1, 8, 27, 64","explanation":""},{"latex":"\\Delta: 1, 7, 19, 37;\\ \\Delta^2: 6, 12, 18;\\ \\Delta^3: 6, 6","explanation":"Third differences are constant for degree 3."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7fe830aeb9cf30', 'les_a621103440d411', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Optimization (maximum volume, minimum cost) means finding where the rate of change switches sign, the central idea of differential calculus."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b50ab98c4f10e', 'les_a621103440d411', 1, 'practice', 'multiple_choice', 1, 'At a local maximum of a polynomial, the rate of change switches from…', '{"choices":["negative to positive","positive to negative","zero to positive","it doesn''t change"],"answer":1}', '[]', 'Rising then falling.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7dd4874c6bc055', 'les_a621103440d411', 2, 'practice', 'multiple_choice', 2, 'Which polynomial has a global maximum?', '{"choices":["$x^3$","$-x^4 + 2x^2$","$x^4$","$x^5 - x$"],"answer":1}', '["Even degree with a negative leading coefficient."]', 'Both ends go down, so it has a highest point.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a9ae23ffabfc7', 'les_a621103440d411', 3, 'practice', 'multiple_choice', 2, 'For a degree-4 polynomial with equal x-steps, which differences are constant?', '{"choices":["First","Second","Third","Fourth"],"answer":3}', '[]', 'The nth differences of a degree-n polynomial are constant.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cfc8d6fed4a54e', 'les_a621103440d411', 4, 'review', 'multiple_choice', 3, 'How many inflection points can a cubic have?', '{"choices":["0","Exactly 1","2","3"],"answer":1}', '[]', 'Every cubic has exactly one inflection point.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a621103440d411', (SELECT id FROM concepts WHERE slug = 'polynomial-functions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d968886662d4b4', 'subj_math', 'concavity', 'Concavity', 'Whether a function''s rate of change is increasing (concave up) or decreasing (concave down).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a621103440d411', (SELECT id FROM concepts WHERE slug = 'concavity'));

-- Lesson: polynomial-rational-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0d93e1a8cf265f', 'polynomial-rational-inequalities', 'Polynomial and rational inequalities', 'Solve polynomial and rational inequalities with critical values and sign charts, and write solutions in interval notation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e3af28622dd88', 'les_0d93e1a8cf265f', 1, 'Rewrite an inequality with 0 on one side and find critical values.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f1487fed9df679', 'les_0d93e1a8cf265f', 2, 'Use a sign chart to decide where the expression is positive or negative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_87f6366464e599', 'les_0d93e1a8cf265f', 3, 'Handle excluded values of rational inequalities correctly.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e3af28622dd88', 'les_0d93e1a8cf265f', 'learn', 1, 'text', '{"body":"A polynomial can change sign only at its zeros, and a rational expression only at zeros of the numerator or denominator. These critical values split the number line into intervals where the sign is constant, so one test value per interval is enough."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1487fed9df679', 'les_0d93e1a8cf265f', 'learn', 2, 'worked_example', '{"title":"Solve $x^2 - x - 6 > 0$","steps":[{"latex":"(x - 3)(x + 2) > 0","explanation":"Critical values −2 and 3."},{"latex":"\\text{test } -3: (+);\\ 0: (-);\\ 4: (+)","explanation":"Sign chart."},{"latex":"(-\\infty, -2) \\cup (3, \\infty)","explanation":"Strict >, so open endpoints."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87f6366464e599', 'les_0d93e1a8cf265f', 'learn', 3, 'worked_example', '{"title":"Solve $\\dfrac{x + 1}{x - 4} \\le 0$","steps":[{"latex":"\\text{critical values } -1,\\ 4","explanation":""},{"latex":"\\text{test } -2: \\tfrac{-}{-} = +;\\ 0: \\tfrac{+}{-} = -;\\ 5: +","explanation":""},{"latex":"[-1, 4)","explanation":"Include −1 (numerator zero, ≤). Exclude 4 (undefined)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d37cc921cb73d1', 'les_0d93e1a8cf265f', 'learn', 4, 'callout', '{"tone":"warning","title":"Don''t multiply by the denominator","body":"Multiplying both sides by $x - 4$ would require knowing its sign. Move everything to one side and use a sign chart instead."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3781217a225aba', 'les_0d93e1a8cf265f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Finding when profit is positive, when a projectile is above a height, or when a concentration exceeds a limit are inequality problems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e3af28622dd88', 'les_0d93e1a8cf265f', 1, 'practice', 'short_text', 2, 'Solve $x^2 - 9 \le 0$. Use interval notation like [-3,3].', '{"accept":["[-3,3]"]}', '[]', '$[-3, 3]$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1487fed9df679', 'les_0d93e1a8cf265f', 2, 'practice', 'short_text', 2, 'Solve $x(x - 5) > 0$. Use the format (-inf,0)U(5,inf).', '{"accept":["(-inf,0)U(5,inf)","(-∞,0)∪(5,∞)","(-inf,0)u(5,inf)"]}', '[]', '$(-\infty, 0) \cup (5, \infty)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87f6366464e599', 'les_0d93e1a8cf265f', 3, 'practice', 'short_text', 2, 'Solve $\dfrac{x - 2}{x + 3} \ge 0$. Use the format (-inf,-3)U[2,inf).', '{"accept":["(-inf,-3)U[2,inf)","(-∞,-3)∪[2,∞)","(-inf,-3)u[2,inf)"]}', '["−3 is excluded."]', '$(-\infty, -3) \cup [2, \infty)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d37cc921cb73d1', 'les_0d93e1a8cf265f', 4, 'review', 'short_text', 3, 'Solve $x^3 - 4x < 0$. Use the format (-inf,-2)U(0,2).', '{"accept":["(-inf,-2)U(0,2)","(-∞,-2)∪(0,2)","(-inf,-2)u(0,2)"]}', '["$x(x - 2)(x + 2)$."]', 'Negative on $(-\infty, -2)$ and $(0, 2)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_51db8d228963b8', 'subj_math', 'sign-analysis', 'Sign analysis', 'Using zeros and undefined points to find where an expression is positive or negative.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0d93e1a8cf265f', (SELECT id FROM concepts WHERE slug = 'sign-analysis'));

-- Lesson: rates-change-linear-quadratic
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_abe497cbccc60f', 'rates-change-linear-quadratic', 'Rates of change in linear and quadratic functions', 'Compare average rates of change of linear and quadratic functions over equal-length intervals: constant for linear, changing at a constant rate for quadratic.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b83964cee325a5', 'les_abe497cbccc60f', 1, 'Compute average rates of change over consecutive equal-length intervals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2823159ef79b57', 'les_abe497cbccc60f', 2, 'Recognize linear functions by constant rates and quadratics by rates that change by a constant amount.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_181c0d2502c2c7', 'les_abe497cbccc60f', 3, 'Use second differences to identify and build quadratic models.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b83964cee325a5', 'les_abe497cbccc60f', 'learn', 1, 'definition', '{"term":"Linear and quadratic patterns","body":"Over consecutive equal-length input intervals, a linear function has a constant average rate of change. A quadratic function''s average rates of change form an arithmetic sequence: the second differences are constant. For $y = ax^2 + bx + c$ with step 1, the second difference is $2a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2823159ef79b57', 'les_abe497cbccc60f', 'learn', 2, 'worked_example', '{"title":"$f(x) = 3x^2 - x$ on $[0, 1], [1, 2], [2, 3]$","steps":[{"latex":"f: 0, 2, 10, 24","explanation":""},{"latex":"\\text{rates: } 2, 8, 14","explanation":"The rate increases by 6 each step."},{"latex":"6 = 2a \\Rightarrow a = 3","explanation":"Second difference 2a."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_181c0d2502c2c7', 'les_abe497cbccc60f', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"A falling object''s average velocity changes by a constant amount each second (constant acceleration), which is exactly the quadratic pattern."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b83964cee325a5', 'les_abe497cbccc60f', 1, 'practice', 'numeric', 1, 'Find the average rate of change of $g(x) = 4x - 7$ on $[2, 10]$.', '{"answer":4}', '[]', 'Linear: always 4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2823159ef79b57', 'les_abe497cbccc60f', 2, 'practice', 'numeric', 2, 'For $f(x) = x^2$, find the average rate of change on $[3, 5]$.', '{"answer":8}', '[]', '$\frac{25 - 9}{2} = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_181c0d2502c2c7', 'les_abe497cbccc60f', 3, 'practice', 'multiple_choice', 2, 'A table has outputs 1, 4, 11, 22, 37 at x = 0, 1, 2, 3, 4. What kind of function fits?', '{"choices":["Linear","Quadratic","Exponential","None"],"answer":1}', '["First differences 3, 7, 11, 15."]', 'Second differences are all 4: quadratic (with $a = 2$).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e8aa30eb2c22ec', 'les_abe497cbccc60f', 4, 'review', 'numeric', 3, 'The second differences of a quadratic table with step 1 are all −6. What is the leading coefficient?', '{"answer":-3}', '[]', '$2a = -6$, $a = -3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e4ff0e38e6f9e3', 'subj_math', 'rate-of-change', 'Average rate of change', 'The change in output divided by the change in input over an interval.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_abe497cbccc60f', (SELECT id FROM concepts WHERE slug = 'rate-of-change'));

-- Lesson: solving-trig-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_601999e1b26461', 'solving-trig-equations', 'Solving trigonometric equations', 'Solve trig equations on [0, 2π) and in general, using inverse functions, factoring, identities and the periodicity of trig functions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d258d8100353d1', 'les_601999e1b26461', 1, 'Find all solutions in [0, 2π) of linear and quadratic trig equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4dbaa89904d01', 'les_601999e1b26461', 2, 'Write general solutions using periodicity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e6f4b64a207d01', 'les_601999e1b26461', 3, 'Use identities and factoring to solve, without dividing out solutions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d258d8100353d1', 'les_601999e1b26461', 'learn', 1, 'text', '{"body":"Trig functions repeat, so a trig equation usually has infinitely many solutions. Find the solutions in one period, then add multiples of the period: $2\\pi$ for sine and cosine, $\\pi$ for tangent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4dbaa89904d01', 'les_601999e1b26461', 'learn', 2, 'worked_example', '{"title":"Solve $2\\sin x + 1 = 0$ on $[0, 2\\pi)$","steps":[{"latex":"\\sin x = -\\tfrac{1}{2}","explanation":""},{"latex":"x = \\tfrac{7\\pi}{6},\\ \\tfrac{11\\pi}{6}","explanation":"Sine is negative in Quadrants III and IV, with reference angle π/6."}],"check":"General solution: $x = \\frac{7\\pi}{6} + 2k\\pi$ or $x = \\frac{11\\pi}{6} + 2k\\pi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6f4b64a207d01', 'les_601999e1b26461', 'learn', 3, 'worked_example', '{"title":"Solve $2\\cos^2 x - \\cos x - 1 = 0$ on $[0, 2\\pi)$","steps":[{"latex":"(2\\cos x + 1)(\\cos x - 1) = 0","explanation":"Factor like a quadratic in cos x."},{"latex":"\\cos x = -\\tfrac{1}{2} \\Rightarrow x = \\tfrac{2\\pi}{3}, \\tfrac{4\\pi}{3};\\quad \\cos x = 1 \\Rightarrow x = 0","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_33aa24ee39b642', 'les_601999e1b26461', 'learn', 4, 'worked_example', '{"title":"Solve $\\sin 2x = \\cos x$ on $[0, 2\\pi)$","steps":[{"latex":"2\\sin x\\cos x - \\cos x = 0 \\Rightarrow \\cos x(2\\sin x - 1) = 0","explanation":"Factor; don''t divide by cos x."},{"latex":"x = \\tfrac{\\pi}{2}, \\tfrac{3\\pi}{2}, \\tfrac{\\pi}{6}, \\tfrac{5\\pi}{6}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1a2134b2374d0', 'les_601999e1b26461', 'experiment', 5, 'activity', '{"activity":"sinusoid","title":"Where does sin x cross a line?","params":{"A":1,"B":1,"C":0,"D":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b528c2040ab660', 'les_601999e1b26461', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"$y = \\sin x + 0.5$ crosses the x-axis where $\\sin x = -0.5$. Read the crossings between 0 and 2π and compare with the first example."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1d6f08b3f0492', 'les_601999e1b26461', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Finding when the tide reaches a certain height, when a Ferris wheel car is at a given level, or when AC voltage crosses a threshold means solving trig equations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d258d8100353d1', 'les_601999e1b26461', 1, 'practice', 'short_text', 1, 'Solve $\cos x = 0$ on $[0, 2\pi)$. Use the format pi/2,3pi/2.', '{"accept":["pi/2,3pi/2","π/2,3π/2"]}', '[]', '$\frac{\pi}{2}, \frac{3\pi}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4dbaa89904d01', 'les_601999e1b26461', 2, 'practice', 'short_text', 2, 'Solve $\tan x = 1$ on $[0, 2\pi)$. Use the format pi/4,5pi/4.', '{"accept":["pi/4,5pi/4","π/4,5π/4"]}', '[]', '$\frac{\pi}{4}, \frac{5\pi}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e6f4b64a207d01', 'les_601999e1b26461', 3, 'practice', 'short_text', 2, 'Solve $2\sin^2 x = 1$ on $[0, 2\pi)$. List in order like pi/4,3pi/4,5pi/4,7pi/4.', '{"accept":["pi/4,3pi/4,5pi/4,7pi/4","π/4,3π/4,5π/4,7π/4"]}', '["$\\sin x = \\pm\\frac{\\sqrt{2}}{2}$."]', 'All four odd multiples of $\frac{\pi}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_33aa24ee39b642', 'les_601999e1b26461', 4, 'review', 'multiple_choice', 3, 'How many solutions does $\sin 3x = 0$ have on $[0, 2\pi)$?', '{"choices":["3","4","6","7"],"answer":2}', '["$3x = k\\pi$ for $0 \\le 3x < 6\\pi$."]', '$k = 0, 1, \dots, 5$: six solutions.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_601999e1b26461', (SELECT id FROM concepts WHERE slug = 'trig-functions'));

-- Lesson: sum-difference-formulas
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dd32bf26b5ca07', 'sum-difference-formulas', 'Sum and difference formulas', 'Use the sum and difference formulas for sine, cosine and tangent to find exact values and verify identities.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3eaebcf6466c40', 'les_dd32bf26b5ca07', 1, 'State the sum and difference formulas for sine, cosine and tangent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_22ecec3c627721', 'les_dd32bf26b5ca07', 2, 'Find exact values such as sin 75° and cos 15°.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3235c121d5f8bb', 'les_dd32bf26b5ca07', 3, 'Use the formulas to simplify expressions and verify identities.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3eaebcf6466c40', 'les_dd32bf26b5ca07', 'learn', 1, 'definition', '{"term":"Formulas","body":"$\\sin(A \\pm B) = \\sin A\\cos B \\pm \\cos A\\sin B$. $\\cos(A \\pm B) = \\cos A\\cos B \\mp \\sin A\\sin B$. $\\tan(A \\pm B) = \\frac{\\tan A \\pm \\tan B}{1 \\mp \\tan A\\tan B}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22ecec3c627721', 'les_dd32bf26b5ca07', 'learn', 2, 'callout', '{"tone":"warning","title":"Not distributive","body":"$\\sin(A + B) \\ne \\sin A + \\sin B$. Check: $\\sin(30^\\circ + 60^\\circ) = 1$, but $\\sin 30^\\circ + \\sin 60^\\circ \\approx 1.37$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3235c121d5f8bb', 'les_dd32bf26b5ca07', 'learn', 3, 'worked_example', '{"title":"Find $\\sin 75^\\circ$ exactly","steps":[{"latex":"\\sin(45^\\circ + 30^\\circ) = \\sin 45^\\circ\\cos 30^\\circ + \\cos 45^\\circ\\sin 30^\\circ","explanation":""},{"latex":"= \\tfrac{\\sqrt{2}}{2}\\cdot\\tfrac{\\sqrt{3}}{2} + \\tfrac{\\sqrt{2}}{2}\\cdot\\tfrac{1}{2} = \\tfrac{\\sqrt{6} + \\sqrt{2}}{4}","explanation":"$\\approx 0.9659$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee824769b97338', 'les_dd32bf26b5ca07', 'learn', 4, 'worked_example', '{"title":"Verify $\\cos\\left(x - \\tfrac{\\pi}{2}\\right) = \\sin x$","steps":[{"latex":"\\cos x\\cos\\tfrac{\\pi}{2} + \\sin x\\sin\\tfrac{\\pi}{2}","explanation":""},{"latex":"= \\cos x \\cdot 0 + \\sin x \\cdot 1 = \\sin x","explanation":"∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61064e03be2935', 'les_dd32bf26b5ca07', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Adding waves (sound, light, AC power) with phase differences uses these formulas, and they''re how rotation matrices combine two rotations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3eaebcf6466c40', 'les_dd32bf26b5ca07', 1, 'practice', 'short_text', 2, 'Find $\cos 15^\circ$ exactly. Use the format (sqrt(6)+sqrt(2))/4.', '{"accept":["(sqrt(6)+sqrt(2))/4","(√6+√2)/4"]}', '["$\\cos(45^\\circ - 30^\\circ)$."]', '$\frac{\sqrt{6} + \sqrt{2}}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22ecec3c627721', 'les_dd32bf26b5ca07', 2, 'practice', 'short_text', 2, 'Find $\sin 15^\circ$ exactly. Use the format (sqrt(6)-sqrt(2))/4.', '{"accept":["(sqrt(6)-sqrt(2))/4","(√6-√2)/4"]}', '[]', '$\sin(45^\circ - 30^\circ) = \frac{\sqrt{6} - \sqrt{2}}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3235c121d5f8bb', 'les_dd32bf26b5ca07', 3, 'practice', 'multiple_choice', 2, 'Simplify $\sin 50^\circ\cos 10^\circ + \cos 50^\circ\sin 10^\circ$.', '{"choices":["$\\sin 40^\\circ$","$\\sin 60^\\circ$","$\\cos 60^\\circ$","$\\cos 40^\\circ$"],"answer":1}', '[]', '$\sin(50^\circ + 10^\circ) = \sin 60^\circ = \frac{\sqrt{3}}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ee824769b97338', 'les_dd32bf26b5ca07', 4, 'review', 'short_text', 3, 'Find $\tan 105^\circ$ exactly. Use the format -2-sqrt(3).', '{"accept":["-2-sqrt(3)","-2-√3"]}', '["$\\tan(60^\\circ + 45^\\circ) = \\frac{\\sqrt{3} + 1}{1 - \\sqrt{3}}$."]', 'Rationalizing gives $-2 - \sqrt{3} \approx -3.732$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dd32bf26b5ca07', (SELECT id FROM concepts WHERE slug = 'trig-identities'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_dd32bf26b5ca07', (SELECT id FROM formulas WHERE slug = 'trig-identities'), 1);

-- Lesson: vectors-in-plane
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d2743a84af9228', 'vectors-in-plane', 'Vectors in the plane', 'Represent vectors in component and magnitude-direction form, add and scale them, find unit vectors, and solve navigation and force problems.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_73140a1e16e314', 'les_d2743a84af9228', 1, 'Write a vector in component form and find its magnitude and direction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8ce3574c1ecb8d', 'les_d2743a84af9228', 2, 'Add, subtract and scale vectors geometrically and algebraically.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c57c29433a190', 'les_d2743a84af9228', 3, 'Find unit vectors and resolve forces and velocities into components.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73140a1e16e314', 'les_d2743a84af9228', 'learn', 1, 'definition', '{"term":"Vector","body":"A quantity with magnitude and direction, drawn as an arrow. In component form $\\mathbf{v} = \\langle a, b \\rangle = a\\mathbf{i} + b\\mathbf{j}$. Magnitude $|\\mathbf{v}| = \\sqrt{a^2 + b^2}$; direction angle $\\theta$ with $\\tan\\theta = \\frac{b}{a}$ (in the right quadrant)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ce3574c1ecb8d', 'les_d2743a84af9228', 'learn', 2, 'definition', '{"term":"Operations","body":"$\\langle a, b \\rangle + \\langle c, d \\rangle = \\langle a + c, b + d \\rangle$ (tip-to-tail). $k\\langle a, b \\rangle = \\langle ka, kb \\rangle$ scales the length by $|k|$ and reverses direction if $k < 0$. A unit vector in the direction of $\\mathbf{v}$ is $\\frac{\\mathbf{v}}{|\\mathbf{v}|}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c57c29433a190', 'les_d2743a84af9228', 'experiment', 3, 'activity', '{"activity":"vectors","title":"Add vectors tip to tail","params":{"ux":4,"uy":1,"vx":-1,"vy":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_33e87307614443', 'les_d2743a84af9228', 'learn', 4, 'worked_example', '{"title":"A plane flies at 300 km/h on a heading of $60^\\circ$ (measured from east) in a wind of 40 km/h blowing toward the east. Find the ground velocity.","steps":[{"latex":"\\mathbf{p} = 300\\langle\\cos 60^\\circ, \\sin 60^\\circ\\rangle = \\langle 150, 259.8 \\rangle","explanation":""},{"latex":"\\mathbf{p} + \\mathbf{w} = \\langle 190, 259.8 \\rangle","explanation":""},{"latex":"|\\cdot| \\approx 321.9 \\text{ km/h},\\ \\theta = \\tan^{-1}\\tfrac{259.8}{190} \\approx 53.8^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d8a1cc188320d8', 'les_d2743a84af9228', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Physics treats forces, velocities and accelerations as vectors; game engines move characters with velocity vectors; GPS navigation combines vectors constantly."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_73140a1e16e314', 'les_d2743a84af9228', 1, 'practice', 'numeric', 1, 'Find the magnitude of $\langle -6, 8 \rangle$.', '{"answer":10}', '[]', '$\sqrt{36 + 64} = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ce3574c1ecb8d', 'les_d2743a84af9228', 2, 'practice', 'short_text', 2, 'Find $2\langle 3, -1 \rangle - \langle 4, 5 \rangle$. Use the format <a,b>.', '{"accept":["<2,-7>","⟨2,-7⟩"]}', '[]', '$\langle 6 - 4, -2 - 5 \rangle = \langle 2, -7 \rangle$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c57c29433a190', 'les_d2743a84af9228', 3, 'practice', 'short_text', 2, 'Find the unit vector in the direction of $\langle 5, 12 \rangle$. Use the format <5/13,12/13>.', '{"accept":["<5/13,12/13>","⟨5/13,12/13⟩"]}', '[]', 'Divide by 13.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_33e87307614443', 'les_d2743a84af9228', 4, 'review', 'numeric', 3, 'A force of 50 N acts at $30^\circ$ above horizontal. Find its horizontal component to the nearest tenth.', '{"answer":43.3,"unit":"N","tolerance":0.06}', '["$50\\cos 30^\\circ$."]', '$25\sqrt{3} \approx 43.3$ N.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7291eb9f68564d', 'subj_math', 'vectors', 'Vectors', 'Quantities with magnitude and direction, written in components.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d2743a84af9228', (SELECT id FROM concepts WHERE slug = 'vectors'));

